  8: // SessionActivity tracks output activity for a single session
  9: type SessionActivity struct {
 10: 	mu         sync.Mutex
 11: 	lastActive time.Time
 12: 	totalBytes int64
 13: }
 14: 
 15: // Snapshot is a point-in-time view of a session's activity
 16: type Snapshot struct {
 17: 	Host        string    `json:"host,omitempty"` // peer fingerprint (empty = local)
 18: 	SessionName string    `json:"session"`
 19: 	IdleSeconds float64   `json:"idle_seconds"`
 20: 	TotalBytes  int64     `json:"total_bytes"`
 21: 	LastActive  time.Time `json:"last_active,omitempty"` // actual time of last recorded activity
 22: }
 23: 
 24: // Tracker tracks output activity across all sessions
 25: type Tracker struct {
 26: 	mu       sync.RWMutex
 27: 	sessions map[string]*SessionActivity
 28: }
 29: 
 30: // NewTracker creates a new activity tracker
 31: func NewTracker() *Tracker {
 32: 	return &Tracker{
 33: 		sessions: make(map[string]*SessionActivity),
 34: 	}
 35: }
 36: 
 37: // Record records output bytes for a session
 38: func (t *Tracker) Record(session string, n int) {
 39: 	t.mu.RLock()
 40: 	sa, ok := t.sessions[session]
 41: 	t.mu.RUnlock()
 42: 
 43: 	if !ok {
 44: 		t.mu.Lock()
 45: 		sa, ok = t.sessions[session]
 46: 		if !ok {
 47: 			sa = &SessionActivity{}
 48: 			t.sessions[session] = sa
 49: 		}
 50: 		t.mu.Unlock()
 51: 	}
 52: 
 53: 	now := time.Now()
 54: 	sa.mu.Lock()
 55: 	defer sa.mu.Unlock()
 56: 
 57: 	sa.lastActive = now
 58: 	sa.totalBytes += int64(n)
 59: }
 60: 
 61: // Get returns a snapshot of a session's activity
 62: func (t *Tracker) Get(session string) *Snapshot {
 63: 	t.mu.RLock()
 64: 	sa, ok := t.sessions[session]
 65: 	t.mu.RUnlock()
 66: 
 67: 	if !ok {
 68: 		return &Snapshot{
 69: 			SessionName: session,
 70: 			IdleSeconds: -1, // never seen
 71: 		}
 72: 	}
 73: 
 74: 	sa.mu.Lock()
 75: 	defer sa.mu.Unlock()
 76: 
 77: 	now := time.Now()
 78: 	idle := now.Sub(sa.lastActive).Seconds()
 79: 
 80: 	return &Snapshot{
 81: 		SessionName: session,
 82: 		IdleSeconds: idle,
 83: 		TotalBytes:  sa.totalBytes,
 84: 		LastActive:  sa.lastActive,
 85: 	}
 86: }
 87: 
 88: // GetAll returns snapshots for all tracked sessions
 89: func (t *Tracker) GetAll() []*Snapshot {
 90: 	t.mu.RLock()
 91: 	names := make([]string, 0, len(t.sessions))
 92: 	for name := range t.sessions {
 93: 		names = append(names, name)
 94: 	}
 95: 	t.mu.RUnlock()
 96: 
 97: 	snapshots := make([]*Snapshot, 0, len(names))
 98: 	for _, name := range names {
 99: 		snapshots = append(snapshots, t.Get(name))
100: 	}
101: 	return snapshots
102: }
103: 
104: // Remove removes tracking for a session
105: func (t *Tracker) Remove(session string) {
106: 	t.mu.Lock()
107: 	delete(t.sessions, session)
108: 	t.mu.Unlock()
