 17: type testBackend struct {
 18: 	mu             sync.Mutex
 19: 	startCalls     []pty.StartRequest
 20: 	startResult    pty.ReadyInfo
 21: 	startErr       error
 22: 	liveGen        map[string]string
 23: 	terminated     map[string]bool
 24: 	terminateCalls []pty.StableBinding
 25: 	terminateOut   pty.TerminateOutcome
 26: }
 27: 
 28: func newTestBackend() *testBackend {
 29: 	return &testBackend{
 30: 		startResult: pty.ReadyInfo{DaemonPID: 42, ShellPID: 43, Generation: "gen-test"},
 31: 		terminateOut: pty.TerminateAcknowledged,
 32: 		liveGen:     make(map[string]string),
 33: 		terminated:  make(map[string]bool),
 34: 	}
 35: }
 36: 
 37: func (b *testBackend) Start(ctx context.Context, req pty.StartRequest) (pty.ReadyInfo, error) {
 38: 	b.mu.Lock()
 39: 	defer b.mu.Unlock()
 40: 	b.startCalls = append(b.startCalls, req)
 41: 	if b.startErr != nil {
 42: 		return pty.ReadyInfo{}, b.startErr
 43: 	}
 44: 	info := b.startResult
 45: 	if info.Generation == "" {
 46: 		info.Generation = "gen-" + string(req.SessionID)
 47: 	}
 48: 	if info.DaemonPID == 0 {
 49: 		info.DaemonPID = 1001 + len(b.startCalls)
 50: 	}
 51: 	b.liveGen[req.SessionID] = info.Generation
 52: 	b.terminated[req.SessionID] = false
 53: 	return info, nil
 54: }
 55: 
 56: func (b *testBackend) Probe(binding pty.StableBinding) pty.ProbeEvidence {
 57: 	b.mu.Lock()
 58: 	defer b.mu.Unlock()
 59: 	if gen, ok := b.liveGen[binding.SessionID]; ok && !b.terminated[binding.SessionID] {
 60: 		return pty.ProbeEvidence{
 61: 			Status:    pty.ProbeLive,
 62: 			Binding:   pty.StableBinding{Owner: binding.Owner, SessionID: binding.SessionID, Generation: gen, DaemonKey: binding.DaemonKey},
 63: 			DaemonPID: 1,
 64: 			Reason:    "test live",
 65: 		}
 66: 	}
 67: 	return pty.ProbeEvidence{Status: pty.ProbeUnknown, Binding: binding}
 68: }
 69: 
 70: func (b *testBackend) Terminate(ctx context.Context, binding pty.StableBinding) pty.TerminateOutcome {
 71: 	b.mu.Lock()
 72: 	defer b.mu.Unlock()
 73: 	b.terminateCalls = append(b.terminateCalls, binding)
 74: 	out := b.terminateOut
 75: 	if out == pty.TerminateAcknowledged {
 76: 		b.terminated[binding.SessionID] = true
 77: 	}
 78: 	return out
 79: }
 80: 
 81: func (b *testBackend) startCount() int {
 82: 	b.mu.Lock()
 83: 	defer b.mu.Unlock()
 84: 	return len(b.startCalls)
 85: }
 86: 
 87: func (b *testBackend) terminateCount() int {
 88: 	b.mu.Lock()
 89: 	defer b.mu.Unlock()
 90: 	return len(b.terminateCalls)
 91: }
