131: func TestCreateReturnsStableIDAndActivates(t *testing.T) {
132: 	svc, catalog, backend, _, cleanup := newTestCommandService(t)
133: 	defer cleanup()
134: 
135: 	ctx, cancel := context.WithCancel(context.Background())
136: 	defer cancel()
137: 	startWorker(ctx, t, svc)
138: 
139: 	cmd := createCmd("alpha")
140: 	res, err := svc.ExecuteSessionCommand(ctx, cmd)
141: 	if err != nil {
142: 		t.Fatalf("create failed: %v", err)
143: 	}
144: 	if !res.Accepted || res.ID != cmd.ID {
145: 		t.Fatalf("unexpected result: %+v", res)
146: 	}
147: 	if res.Ref.Session == "" {
148: 		t.Fatal("expected stable session ref")
149: 	}
150: 
151: 	// Before the worker runs, only the pending intent and layout exist.
152: 	if p := catalog.PendingCreates(); len(p) != 1 {
153: 		t.Fatalf("expected 1 pending create, got %d", len(p))
154: 	}
155: 	layouts := catalog.Layouts()
156: 	if len(layouts) != 1 {
157: 		t.Fatalf("expected 1 layout, got %d", len(layouts))
158: 	}
159: 
160: 	// Wait for the worker to start the daemon and commit the running record.
161: 	for start := time.Now(); time.Since(start) < 5*time.Second; {
162: 		if r, ok := catalog.Session(res.Ref.Session); ok && r.Phase == SessionPhaseActive {
163: 			break
164: 		}
165: 		time.Sleep(10 * time.Millisecond)
166: 	}
167: 
168: 	rec, ok := catalog.Session(res.Ref.Session)
169: 	if !ok || rec.Phase != SessionPhaseActive {
170: 		t.Fatalf("expected active session: %+v", rec)
171: 	}
172: 	if rec.Compat.Generation == "" {
173: 		t.Fatal("expected generation set")
174: 	}
175: 	if backend.startCount() != 1 {
176: 		t.Fatalf("expected one daemon start, got %d", backend.startCount())
177: 	}
178: 	if catalog.PendingCreates(); len(catalog.PendingCreates()) != 0 {
179: 		t.Fatalf("pending create should be removed")
180: 	}
181: }
