183: func TestCreateDurableBeforeAsyncWork(t *testing.T) {
184: 	svc, catalog, _, store, cleanup := newTestCommandService(t)
185: 	defer cleanup()
186: 
187: 	var panicked bool
188: 	svc.opts.CrashHook = func(p CrashPoint) {
189: 		if p == CrashAfterIntentCommit && !panicked {
190: 			panicked = true
191: 			panic("crash after intent commit")
192: 		}
193: 	}
194: 
195: 	cmd := createCmd("beta")
196: 	func() {
197: 		defer func() {
198: 			if r := recover(); r != nil {
199: 				// expected
200: 			}
201: 		}()
202: 		_, _ = svc.ExecuteSessionCommand(context.Background(), cmd)
203: 	}()
204: 
205: 	pendingList := catalog.PendingCreates()
206: 	if len(pendingList) != 1 {
207: 		t.Fatalf("expected pending create to survive crash, got %d", len(pendingList))
208: 	}
209: 
210: 	// Simulate restart by opening a new catalog/service on the same store.
211: 	fresh := NewCatalog(store.Owner(), store)
212: 	_ = fresh.Load()
213: 	recovered := NewSessionCommandService(fresh, newTestBackend(), nil, SessionCommandServiceOptions{Tick: 50 * time.Millisecond})
214: 
215: 	ctx, cancel := context.WithCancel(context.Background())
216: 	defer cancel()
217: 	startWorker(ctx, t, recovered)
218: 
219: 	for start := time.Now(); time.Since(start) < 5*time.Second; {
220: 		if _, ok := fresh.Session(pendingList[0].Ref.Session); ok {
221: 			break
222: 		}
223: 		time.Sleep(10 * time.Millisecond)
224: 	}
225: 	if _, ok := fresh.Session(pendingList[0].Ref.Session); !ok {
226: 		t.Fatal("expected recovered create to finish")
227: 	}
228: }
