230: func TestDuplicateCommandIDIsIdempotent(t *testing.T) {
231: 	svc, catalog, backend, _, cleanup := newTestCommandService(t)
232: 	defer cleanup()
233: 
234: 	ctx, cancel := context.WithCancel(context.Background())
235: 	defer cancel()
236: 	startWorker(ctx, t, svc)
237: 
238: 	cmd := createCmd("gamma")
239: 	res1, err := svc.ExecuteSessionCommand(ctx, cmd)
240: 	if err != nil {
241: 		t.Fatal(err)
242: 	}
243: 	res2, err := svc.ExecuteSessionCommand(ctx, cmd)
244: 	if err != nil {
245: 		t.Fatal(err)
246: 	}
247: 	if res1.Ref.Session != res2.Ref.Session {
248: 		t.Fatalf("idempotency produced different refs: %v vs %v", res1.Ref.Session, res2.Ref.Session)
249: 	}
250: 	// Wait for the worker to start the daemon and commit the running record.
251: 	for start := time.Now(); time.Since(start) < 5*time.Second; {
252: 		if r, ok := catalog.Session(res1.Ref.Session); ok && r.Phase == SessionPhaseActive {
253: 			break
254: 		}
255: 		time.Sleep(10 * time.Millisecond)
256: 	}
257: 	rec, ok := catalog.Session(res1.Ref.Session)
258: 	if !ok || rec.Phase != SessionPhaseActive {
259: 		t.Fatalf("expected active session: %+v", rec)
260: 	}
261: 	if backend.startCount() != 1 {
262: 		t.Fatalf("expected one daemon start, got %d", backend.startCount())
263: 	}
264: 	if len(catalog.Sessions()) != 1 {
265: 		t.Fatalf("expected one session, got %d", len(catalog.Sessions()))
266: 	}
267: }
