269: func TestConcurrentCreateSameRefProducesOneSession(t *testing.T) {
270: 	svc, catalog, backend, _, cleanup := newTestCommandService(t)
271: 	defer cleanup()
272: 
273: 	ctx, cancel := context.WithCancel(context.Background())
274: 	defer cancel()
275: 	startWorker(ctx, t, svc)
276: 
277: 	ref := SessionRef{Owner: testOwner(), Session: NewSessionID(), Window: 0, Pane: 0}
278: 	cmdID := NewCommandID()
279: 	params, _ := json.Marshal(CreateParams{Name: "delta", Shell: "/bin/bash", Cwd: "/tmp"})
280: 
281: 	var wg sync.WaitGroup
282: 	for i := 0; i < 10; i++ {
283: 		wg.Add(1)
284: 		go func() {
285: 			defer wg.Done()
286: 			_, _ = svc.ExecuteSessionCommand(ctx, SessionCommand{ID: cmdID, Ref: ref, Action: ActionCreate, Params: params})
287: 		}()
288: 	}
289: 	wg.Wait()
290: 
291: 	if sessions := catalog.Sessions(); len(sessions)+len(catalog.PendingCreates()) != 1 {
292: 		t.Fatalf("expected one session or pending, got sessions=%d pending=%d", len(sessions), len(catalog.PendingCreates()))
293: 	}
294: 	for start := time.Now(); time.Since(start) < 5*time.Second; {
295: 		if backend.startCount() == 1 {
296: 			break
297: 		}
298: 		time.Sleep(10 * time.Millisecond)
299: 	}
300: 	if backend.startCount() != 1 {
301: 		t.Fatalf("expected one daemon start across concurrent creates, got %d", backend.startCount())
302: 	}
303: }
