305: func TestCreateWorktreeCleanedOnPermanentFailure(t *testing.T) {
306: 	repo := initGitRepo(t)
307: 	t.Setenv("HOME", t.TempDir())
308: 
309: 	svc, catalog, backend, _, cleanup := newTestCommandService(t)
310: 	defer cleanup()
311: 
312: 	backend.startErr = errors.New("spawn failed")
313: 	svc.opts.MaxCreateRetries = 1
314: 
315: 	ctx, cancel := context.WithCancel(context.Background())
316: 	defer cancel()
317: 	startWorker(ctx, t, svc)
318: 
319: 	cmdID := NewCommandID()
320: 	params, _ := json.Marshal(CreateParams{
321: 		Name:           "feat",
322: 		Shell:          "/bin/bash",
323: 		Cwd:            repo,
324: 		WorktreeBranch: "feature",
325: 		Cols:           80,
326: 		Rows:           24,
327: 	})
328: 	res, err := svc.ExecuteSessionCommand(ctx, SessionCommand{ID: cmdID, Action: ActionCreate, Params: params})
329: 	if err != nil {
330: 		t.Fatal(err)
331: 	}
332: 
333: 	worktreePath := filepath.Join(repo, ".worktrees", "feature")
334: 	if _, err := os.Stat(worktreePath); err == nil {
335: 		t.Fatal("worktree should not exist before worker prepares it")
336: 	}
337: 
338: 	// Wait for worker to exhaust retries.
339: 	for start := time.Now(); time.Since(start) < 3*time.Second; {
340: 		if rec, ok := catalog.Session(res.Ref.Session); ok && rec.Phase == SessionPhaseDismissed {
341: 			break
342: 		}
343: 		time.Sleep(20 * time.Millisecond)
344: 	}
345: 
346: 	rec, ok := catalog.Session(res.Ref.Session)
347: 	if !ok || rec.Phase != SessionPhaseDismissed {
348: 		t.Fatalf("expected dismissed record after retries exhausted: %+v", rec)
349: 	}
350: 	// The directory removal happens after the catalog write; give it a moment.
351: 	time.Sleep(100 * time.Millisecond)
352: 	if _, err := os.Stat(worktreePath); !os.IsNotExist(err) {
353: 		t.Fatalf("failed-create worktree should be removed: %v", err)
354: 	}
355: }
