480: 	_ = catalog.PutLayout(layout)
481: 
482: 	backend := newFakeBackend()
483: 	backend.setProbe(bindingForRecord(&rec), pty.ProbeEvidence{
484: 		Status: pty.ProbeClean,
485: 		Binding: pty.StableBinding{
486: 			Owner:      string(owner),
487: 			SessionID:  string(rec.ID),
488: 			Generation: "gen-exit",
489: 		},
490: 	})
491: 
492: 	r := NewReconciler(catalog, backend, nil, ReconcilerOptions{})
493: 	if err := r.ReconcileOnce(context.Background()); err != nil {
494: 		t.Fatal(err)
495: 	}
496: 
497: 	if _, ok := catalog.Session(rec.ID); ok {
498: 		t.Fatal("expected clean session removed")
499: 	}
500: 	if len(catalog.Layouts()) != 0 {
501: 		t.Fatalf("expected empty layout removed after clean exit, got %d", len(catalog.Layouts()))
502: 	}
503: }
