505: func TestCrashAfterDaemonReadyResumesWithoutDuplicate(t *testing.T) {
506: 	svc, catalog, backend, store, cleanup := newTestCommandService(t)
507: 	defer cleanup()
508: 
509: 	cmd := createCmd("resume")
510: 	_, err := svc.ExecuteSessionCommand(context.Background(), cmd)
511: 	if err != nil {
512: 		t.Fatal(err)
513: 	}
514: 	pending := catalog.PendingCreates()[0]
515: 
516: 	var panicked bool
517: 	svc.opts.CrashHook = func(p CrashPoint) {
518: 		if p == CrashAfterDaemonReady && !panicked {
519: 			panicked = true
520: 			panic("crash after daemon ready")
521: 		}
522: 	}
523: 	func() {
524: 		defer func() {
525: 			if r := recover(); r != nil {
526: 				// expected
527: 			}
528: 		}()
529: 		svc.executePendingCreate(context.Background(), pending)
530: 	}()
531: 
532: 	if backend.startCount() != 1 {
533: 		t.Fatalf("expected one start attempt before crash, got %d", backend.startCount())
534: 	}
535: 
536: 	fresh := NewCatalog(store.Owner(), store)
537: 	_ = fresh.Load()
538: 	recovered := NewSessionCommandService(fresh, backend, nil, SessionCommandServiceOptions{Tick: 50 * time.Millisecond})
539: 	ctx, cancel := context.WithCancel(context.Background())
540: 	defer cancel()
541: 	startWorker(ctx, t, recovered)
542: 
543: 	for start := time.Now(); time.Since(start) < 5*time.Second; {
544: 		if r, ok := fresh.Session(pending.Ref.Session); ok && r.Phase == SessionPhaseActive {
545: 			break
546: 		}
547: 		time.Sleep(10 * time.Millisecond)
548: 	}
549: 	if backend.startCount() != 1 {
550: 		t.Fatalf("resume should not restart a ready daemon, got %d starts", backend.startCount())
551: 	}
552: }
