 30: func TestRuntimeReadyWithoutPolling(t *testing.T) {
 31: 	// The runtime must become ready immediately; any 10 ms hub-polling loop
 32: 	// would introduce visible latency here.
 33: 	rt, err := newRuntime(&cli.Command{})
 34: 	if err != nil {
 35: 		t.Fatalf("newRuntime: %v", err)
