 43: 	}
 44: 	defer rt.Stop()
 45: 
 46: 	select {
 47: 	case <-rt.Ready():
 48: 	case <-ctx.Done():
 49: 		t.Fatal("runtime did not become ready before context timeout")
 50: 	}
