 74: func TestDaemonAdapterSharesSnapshot(t *testing.T) {
 75: 	reg := &fakeRegistry{
 76: 		sessions: []pty.SessionInfo{
 77: 			{ID: "alpha", Cwd: "/tmp/alpha"},
 78: 			{ID: "beta", Cwd: "/tmp/beta"},
 79: 		},
 80: 	}
 81: 	adapter := &daemonAdapter{reg: reg}
 82: 
 83: 	// Both interface shapes can be assigned without a second conversion.
 84: 	var _ state.DaemonRegistry = adapter
 85: 	var _ peer.DaemonRegistry = adapter
 86: 
 87: 	first := adapter.refresh()
 88: 	if len(first) != 2 {
 89: 		t.Fatalf("refresh returned %d sessions, want 2", len(first))
 90: 	}
 91: 
 92: 	// List uses the cached snapshot; it does not call the registry again.
 93: 	list := adapter.List()
 94: 	if reg.listCalls != 1 {
 95: 		t.Fatalf("registry.List called %d times, want 1", reg.listCalls)
 96: 	}
 97: 	if len(list) != len(first) {
 98: 		t.Fatalf("List returned %d sessions, want %d", len(list), len(first))
 99: 	}
100: 
101: 	// Mutating the returned slice must not affect later callers.
102: 	list[0].ID = "mutated"
103: 	if got := adapter.List()[0].ID; got != "alpha" {
104: 		t.Fatalf("shared slice was mutated through List copy: got %q", got)
105: 	}
106: }
