124: // TestRefreshDaemonState_ClassifiesBeforePublishing verifies that crash
125: // classification/cleanup runs before the live state snapshot is published.
126: // A crashed session must not appear as live in the same refresh cycle.
127: func TestRefreshDaemonState_ClassifiesBeforePublishing(t *testing.T) {
128: 	var order []string
129: 	reg := &fakeRegistry{sessions: []pty.SessionInfo{{ID: "live"}}}
130: 	adapter := &daemonAdapter{reg: reg}
131: 
132: 	rt := &Runtime{
133: 		adapter:  adapter,
134: 		stateMgr: state.NewManager(),
135: 		detectCrashesFn: func() []pty.LifecycleRecord {
136: 			order = append(order, "classify")
137: 			return []pty.LifecycleRecord{{ID: "crashed"}}
138: 		},
139: 	}
140: 
141: 	rt.refreshDaemonState()
142: 
143: 	if len(order) != 1 || order[0] != "classify" {
144: 		t.Fatalf("expected classify call, got %v", order)
145: 	}
146: 	if reg.listCalls != 1 {
147: 		t.Fatalf("expected adapter.List after classify, listCalls=%d", reg.listCalls)
148: 	}
149: 
150: 	sessions := rt.stateMgr.GetSessions()
151: 	if len(sessions) != 1 || sessions[0].Name != "live" {
152: 		t.Fatalf("expected only live session in state, got %+v", sessions)
153: 	}
154: }
