156: // TestV2RuntimeEnricherPreviewReturnsImmediately verifies that previewFor returns
157: // cached values immediately without blocking on PTY captures. The enricher must
158: // not delay catalog snapshot publication by waiting for capture operations.
159: func TestV2RuntimeEnricherPreviewReturnsImmediately(t *testing.T) {
160: 	denricher := &v2RuntimeEnricher{
161: 		adapter:    &daemonAdapter{reg: &fakeRegistry{sessions: []pty.SessionInfo{{ID: "s1", Pid: 100, ShellPid: 101}}}},
162: 		actTracker: nil,
163: 	}
164: 
165: 	// First call to previewFor returns immediately with cached (empty) value.
166: 	start := time.Now()
167: 	preview1 := denricher.previewFor("s1")
168: 	elapsed := time.Since(start)
169: 
170: 	if elapsed > 50*time.Millisecond {
171: 		t.Fatalf("previewFor took %v, should be instant", elapsed)
172: 	}
173: 	if preview1 != "" {
174: 		t.Fatalf("first previewFor should return empty cache, got %q", preview1)
175: 	}
176: 
177: 	// Concurrent calls also return immediately.
178: 	start = time.Now()
179: 	for i := 0; i < 5; i++ {
180: 		preview := denricher.previewFor("s1")
181: 		if preview != "" {
182: 			t.Fatalf("previewFor should return empty cache, got %q", preview)
183: 		}
184: 	}
185: 	elapsed = time.Since(start)
186: 
187: 	if elapsed > 50*time.Millisecond {
188: 		t.Fatalf("concurrent previewFor calls took %v, should be instant", elapsed)
189: 	}
190: }
