205: 		adapter:    &daemonAdapter{reg: &fakeRegistry{sessions: []pty.SessionInfo{{ID: "s1", Pid: 100, ShellPid: 101}}}},
206: 		actTracker: tracker,
207: 	}
208: 
209: 	rec := state.LocalSessionRecord{
210: 		ID:    state.SessionID("s1"),
211: 		Owner: ref.Owner,
212: 		Ref:   ref,
213: 	}
214: 
215: 	// Refresh adapter snapshot so sessions are visible.
216: 	enricher.adapter.refresh()
217: 
218: 	// Without activity evidence, LastActivity should be zero.
219: 	rt := enricher.Enrich(ref, rec)
220: 	if !rt.LastActivity.IsZero() {
221: 		t.Fatalf("without activity evidence, LastActivity should be zero, got %v", rt.LastActivity)
222: 	}
223: 
224: 	// Record activity bytes. The tracker records activity with current time.
225: 	tracker.Record("s1", 100)
226: 
227: 	// Enricher should now report LastActivity based on tracker evidence.
228: 	rt = enricher.Enrich(ref, rec)
229: 	if rt.LastActivity.IsZero() {
230: 		t.Fatal("with activity evidence, LastActivity should not be zero")
231: 	}
232: 
233: 	// Verify time is recent (within last second).
234: 	now := time.Now()
235: 	diff := now.Sub(rt.LastActivity)
236: 	if diff < 0 || diff > time.Second {
237: 		t.Fatalf("LastActivity should be recent, got %v (diff from now: %v)", rt.LastActivity, diff)
238: 	}
239: }
