241: // TestV2RuntimeEnricherLastActivityNotBumpedByReEnrichment verifies that a stale
242: // session's LastActivity doesn't get refreshed just by being enriched repeatedly.
243: func TestV2RuntimeEnricherLastActivityNotBumpedByReEnrichment(t *testing.T) {
244: 	tracker := activity.NewTracker()
245: 
246: 	ref := state.SessionRef{
247: 		Owner:   state.OwnerID("testowner"),
248: 		Session: state.SessionID("stale"),
249: 		Window:  0,
250: 		Pane:    0,
251: 	}
252: 
253: 	enricher := &v2RuntimeEnricher{
254: 		adapter:    &daemonAdapter{reg: &fakeRegistry{sessions: []pty.SessionInfo{{ID: "stale", Pid: 100, ShellPid: 101}}}},
255: 		actTracker: tracker,
256: 	}
257: 
258: 	rec := state.LocalSessionRecord{
259: 		ID:    state.SessionID("stale"),
260: 		Owner: ref.Owner,
261: 		Ref:   ref,
262: 	}
263: 
264: 	// Refresh adapter snapshot so sessions are visible.
265: 	enricher.adapter.refresh()
266: 
267: 	// Record activity once.
268: 	tracker.Record("stale", 1)
269: 
270: 	// Enrich once, get the LastActivity.
271: 	rt1 := enricher.Enrich(ref, rec)
272: 	if rt1.LastActivity.IsZero() {
273: 		t.Fatal("expected LastActivity from tracker")
274: 	}
275: 	firstTime := rt1.LastActivity
276: 
277: 	// Wait a bit, then enrich again without recording new activity.
278: 	time.Sleep(100 * time.Millisecond)
279: 	rt2 := enricher.Enrich(ref, rec)
280: 
281: 	// LastActivity should NOT have been bumped to time.Now(). The second
282: 	// enrichment should report the same (or very close) time since no new
283: 	// activity was recorded. The tracker's IdleSeconds will be higher, but
284: 	// the reported LastActivity time should remain stable.
285: 	diff := rt2.LastActivity.Sub(firstTime).Abs()
286: 	if diff > 50*time.Millisecond {
287: 		t.Fatalf("LastActivity should not change on re-enrichment without new activity: %v vs %v (diff: %v)",
288: 			firstTime, rt2.LastActivity, diff)
289: 	}
