 32: func TestUnregisterPeerConn_StaleCannotReplaceLive(t *testing.T) {
 33: 	mgr := makeV2Manager(t)
 34: 	remoteID, err := identity.Generate("remote")
 35: 	if err != nil {
 36: 		t.Fatal(err)
 37: 	}
 38: 	fp := remoteID.Fingerprint()
 39: 
 40: 	oldConn := NewPeerConnection(fp, 64)
 41: 	mgr.RegisterPeer(fp, "remote", remoteID.PublicKey, oldConn)
 42: 
 43: 	// Replacement arrives before the old connection closes.
 44: 	newConn := NewPeerConnection(fp, 64)
 45: 	mgr.RegisterPeer(fp, "remote", remoteID.PublicKey, newConn)
 46: 
 47: 	if mgr.GetPeerConnection(fp) != newConn {
 48: 		t.Fatal("expected new connection to be live")
 49: 	}
 50: 
 51: 	// Old connection closes late; it must not unregister the replacement.
 52: 	mgr.UnregisterPeerConn(fp, oldConn)
 53: 	if mgr.GetPeerConnection(fp) != newConn {
 54: 		t.Fatal("stale connection unregistered the replacement")
 55: 	}
 56: 
 57: 	// New connection closes with itself; it should unregister.
 58: 	mgr.UnregisterPeerConn(fp, newConn)
 59: 	if mgr.GetPeerConnection(fp) != nil {
 60: 		t.Fatal("expected no live connection after new conn closes")
 61: 	}
 62: }
