 93: func TestRemoteCatalog_PreservedThroughReconnect(t *testing.T) {
 94: 	mgr := makeV2Manager(t)
 95: 	remoteID, err := identity.Generate("remote")
 96: 	if err != nil {
 97: 		t.Fatal(err)
 98: 	}
 99: 	fp := remoteID.Fingerprint()
100: 	owner := state.OwnerID(fp)
101: 	s1 := state.LocalSessionRecord{ID: "s1", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s1"}}
102: 
103: 	conn := NewPeerConnection(fp, 64)
104: 	mgr.RegisterPeer(fp, "remote", remoteID.PublicKey, conn)
105: 	mgr.UpdateRemoteCatalog(fp, state.OwnerCatalogSnapshot{
106: 		Owner:    owner,
107: 		Revision: 1,
108: 		Sessions: []state.LocalSessionRecord{s1},
109: 	})
110: 
111: 	// Connection drops.
112: 	mgr.UnregisterPeerConn(fp, conn)
113: 
114: 	// Catalog must survive disconnect.
115: 	snap, ok := mgr.RemoteCatalogSnapshot(owner)
116: 	if !ok {
117: 		t.Fatal("expected catalog to survive disconnect")
118: 	}
119: 	if len(snap.Sessions) != 1 {
120: 		t.Fatalf("expected 1 session, got %d", len(snap.Sessions))
121: 	}
122: 
123: 	// Replacement registers; old catalog is still visible until a newer
124: 	// snapshot arrives.
125: 	newConn := NewPeerConnection(fp, 64)
126: 	mgr.RegisterPeer(fp, "remote", remoteID.PublicKey, newConn)
127: 	snap, ok = mgr.RemoteCatalogSnapshot(owner)
128: 	if !ok || len(snap.Sessions) != 1 {
129: 		t.Fatal("replacement registration should preserve prior catalog")
130: 	}
131: 
132: 	// Newer snapshot overwrites.
133: 	s2 := state.LocalSessionRecord{ID: "s2", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s2"}}
134: 	mgr.UpdateRemoteCatalog(fp, state.OwnerCatalogSnapshot{
135: 		Owner:    owner,
136: 		Revision: 2,
137: 		Sessions: []state.LocalSessionRecord{s2},
138: 	})
139: 	snap, _ = mgr.RemoteCatalogSnapshot(owner)
140: 	if len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s2" {
141: 		t.Fatalf("expected new snapshot to replace prior catalog, got %+v", snap.Sessions)
142: 	}
143: }
