197: func TestHandleV2CatalogSnapshot_UpdatesCache(t *testing.T) {
198: 	mgr := makeV2Manager(t)
199: 	peerID := "remote-a"
200: 	// The wire round-trip requires a canonical (lowercase base32) OwnerID; it
201: 	// need not equal the peer id -- the manager binds peer -> owner instead.
202: 	owner := state.OwnerID("remotea123")
203: 	sessionID := state.NewSessionID()
204: 	s1 := state.LocalSessionRecord{ID: sessionID, Owner: owner, Ref: state.SessionRef{Owner: owner, Session: sessionID}}
205: 
206: 	payload := V2CatalogSnapshotPayload{
207: 		Owner:    owner,
208: 		Revision: 1,
209: 		Sessions: []state.LocalSessionRecord{s1},
210: 	}
211: 	msg, err := NewMessage(MsgV2CatalogSnapshot, payload)
212: 	if err != nil {
213: 		t.Fatal(err)
214: 	}
215: 	pc := NewPeerConnection(peerID, 64)
216: 	deps := SessionDeps{Manager: mgr, LocalMgr: mgr.localMgr}
217: 
218: 	handleV2Message(peerID, msg, pc, deps, testLogger(t))
219: 
220: 	snap, ok := mgr.RemoteCatalogSnapshot(owner)
221: 	if !ok {
222: 		t.Fatal("expected cache update")
223: 	}
224: 	if len(snap.Sessions) != 1 || snap.Sessions[0].ID != sessionID {
225: 		t.Fatalf("unexpected cached sessions: %+v", snap.Sessions)
226: 	}
227: }
