301: // TestRemoteSnapshot_OwnerBindingEnforced proves a peer may publish under
302: // exactly one owner and no two peers may share an owner: a peer switching
303: // owners or a second peer claiming a bound owner is dropped.
304: func TestRemoteSnapshot_OwnerBindingEnforced(t *testing.T) {
305: 	mgr := makeV2Manager(t)
306: 	peerA := "peer-a"
307: 	peerB := "peer-b"
308: 	ownerA := state.OwnerID("ownera1")
309: 	ownerB := state.OwnerID("ownerb2")
310: 
311: 	// First snapshot from peerA binds ownerA.
312: 	mgr.UpdateRemoteCatalog(peerA, state.OwnerCatalogSnapshot{
313: 		Owner:    ownerA,
314: 		Revision: 1,
315: 		Sessions: []state.LocalSessionRecord{{ID: "s1", Owner: ownerA, Ref: state.SessionRef{Owner: ownerA, Session: "s1"}}},
316: 	})
317: 	if _, ok := mgr.RemoteCatalogSnapshot(ownerA); !ok {
318: 		t.Fatal("expected peerA ownerA catalog cached")
319: 	}
320: 
321: 	// peerB claiming ownerA is a spoof -> dropped.
322: 	mgr.UpdateRemoteWorkspace(peerB, state.WorkspaceRecord{
323: 		ID:       "layout1",
324: 		Owner:    ownerA,
325: 		Revision: 1,
326: 		Tree:     state.Leaf(state.SessionRef{Owner: ownerA, Session: "s1"}),
327: 	})
328: 	if _, ok := mgr.RemoteWorkspaceSnapshot(ownerA); ok {
329: 		t.Fatal("spoofed workspace under bound owner accepted")
330: 	}
331: 	mgr.UpdateRemoteCatalog(peerB, state.OwnerCatalogSnapshot{Owner: ownerA, Revision: 1})
332: 	if _, ok := mgr.RemoteCatalogSnapshot(ownerA); ok {
333: 		// Still peerA's catalog; peerB's attempt must not replace it.
334: 		snap, _ := mgr.RemoteCatalogSnapshot(ownerA)
335: 		if len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s1" {
336: 			t.Fatalf("peerB overwrote bound owner catalog: %+v", snap.Sessions)
337: 		}
338: 	}
339: 
340: 	// peerB may bind its own distinct owner.
341: 	mgr.UpdateRemoteCatalog(peerB, state.OwnerCatalogSnapshot{Owner: ownerB, Revision: 1})
342: 	if _, ok := mgr.RemoteCatalogSnapshot(ownerB); !ok {
343: 		t.Fatal("expected peerB own-owner catalog cached")
344: 	}
345: 
346: 	// peerA switching to ownerB is rejected (one owner per peer).
347: 	mgr.UpdateRemoteCatalog(peerA, state.OwnerCatalogSnapshot{Owner: ownerB, Revision: 2})
348: 	snap, _ := mgr.RemoteCatalogSnapshot(ownerB)
349: 	if len(snap.Sessions) != 0 {
350: 		t.Fatalf("peerA published under peerB's owner: %+v", snap.Sessions)
351: 	}
352: }
