354: func TestRemoteCatalog_StaleRevisionRejected(t *testing.T) {
355: 	mgr := makeV2Manager(t)
356: 	peerID := "peer-a"
357: 	owner := state.OwnerID(peerID)
358: 	s1 := state.LocalSessionRecord{ID: "s1", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s1"}}
359: 	s2 := state.LocalSessionRecord{ID: "s2", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s2"}}
360: 
361: 	mgr.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{Owner: owner, Revision: 1, Sessions: []state.LocalSessionRecord{s1}})
362: 
363: 	// Equal revision (delayed duplicate) must not regress the cache.
364: 	mgr.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{Owner: owner, Revision: 1, Sessions: []state.LocalSessionRecord{s2}})
365: 	snap, _ := mgr.RemoteCatalogSnapshot(owner)
366: 	if len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s1" {
367: 		t.Fatalf("equal-revision snapshot regressed cache: %+v", snap.Sessions)
368: 	}
369: 
370: 	// Lower revision (stale/delayed) must be dropped too.
371: 	mgr.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{Owner: owner, Revision: 0, Sessions: []state.LocalSessionRecord{s2}})
372: 	snap, _ = mgr.RemoteCatalogSnapshot(owner)
373: 	if len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s1" {
374: 		t.Fatalf("lower-revision snapshot regressed cache: %+v", snap.Sessions)
375: 	}
376: 
377: 	// A new connection is a new generation: the baseline resets, so the same
378: 	// numeric revision is accepted again.
379: 	mgr.RegisterPeer(peerID, "peer-a", "", NewPeerConnection(peerID, 64))
380: 	mgr.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{Owner: owner, Revision: 1, Sessions: []state.LocalSessionRecord{s2}})
381: 	snap, ok := mgr.RemoteCatalogSnapshot(owner)
382: 	if !ok || len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s2" {
383: 		t.Fatalf("reconnect baseline should accept revision 1 again, got %+v (ok=%v)", snap.Sessions, ok)
384: 	}
385: }
