387: func TestRemoteWorkspace_StaleRevisionRejected(t *testing.T) {
388: 	mgr := makeV2Manager(t)
389: 	peerID := "peer-a"
390: 	owner := state.OwnerID(peerID)
391: 	leafA := state.Leaf(state.SessionRef{Owner: owner, Session: "s1"})
392: 	leafB := state.Leaf(state.SessionRef{Owner: owner, Session: "s2"})
393: 
394: 	mgr.UpdateRemoteWorkspace(peerID, state.WorkspaceRecord{ID: "layout1", Owner: owner, Revision: 5, Tree: leafA})
395: 
396: 	// Same layout, equal revision -> rejected.
397: 	mgr.UpdateRemoteWorkspace(peerID, state.WorkspaceRecord{ID: "layout1", Owner: owner, Revision: 5, Tree: leafB})
398: 	ws, _ := mgr.RemoteWorkspaceSnapshot(owner)
399: 	if ws.Tree.Ref == nil || ws.Tree.Ref.Session != "s1" {
400: 		t.Fatalf("equal-revision workspace regressed cache")
401: 	}
402: 
403: 	// Same layout, lower revision -> rejected.
404: 	mgr.UpdateRemoteWorkspace(peerID, state.WorkspaceRecord{ID: "layout1", Owner: owner, Revision: 4, Tree: leafB})
405: 	ws, _ = mgr.RemoteWorkspaceSnapshot(owner)
406: 	if ws.Tree.Ref == nil || ws.Tree.Ref.Session != "s1" {
407: 		t.Fatalf("lower-revision workspace regressed cache")
408: 	}
409: 
410: 	// A different layout has its own revision baseline.
411: 	mgr.UpdateRemoteWorkspace(peerID, state.WorkspaceRecord{ID: "layout2", Owner: owner, Revision: 1, Tree: leafB})
412: 	ws, ok := mgr.RemoteWorkspaceSnapshot(owner)
413: 	if !ok || ws.ID != "layout2" {
414: 		t.Fatalf("independent workspace revisions should be accepted: %+v", ws)
415: 	}
416: }
