436: 	mgr.UpdateRemoteCatalog(fp, state.OwnerCatalogSnapshot{Owner: owner, Revision: 1, Sessions: []state.LocalSessionRecord{s1}})
437: 
438: 	if _, ok := mgr.RemoteCatalogSnapshot(owner); !ok {
439: 		t.Fatal("expected cached catalog before forget")
440: 	}
441: 
442: 	mgr.RemoveHost(fp)
443: 	if _, ok := mgr.RemoteCatalogSnapshot(owner); ok {
444: 		t.Fatal("catalog should be cleared on RemoveHost")
445: 	}
446: 
447: 	// Simulated reload from the persisted sidecar: the forget must be durable
448: 	// so the peer does not reappear after a restart.
449: 	if err := mgr.LoadRemoteCatalogCache(); err != nil {
450: 		t.Fatal(err)
451: 	}
452: 	if _, ok := mgr.RemoteCatalogSnapshot(owner); ok {
453: 		t.Fatal("forgotten peer reappeared after reload")
454: 	}
455: }
