457: // TestRemoteSnapshot_SpoofedSessionOwnerRejected proves that a snapshot
458: // containing a session with embedded owner != snap.Owner is rejected.
459: func TestRemoteSnapshot_SpoofedSessionOwnerRejected(t *testing.T) {
460: 	mgr := makeV2Manager(t)
461: 	peerID := "peer-a"
462: 	owner := state.OwnerID("owner1")
463: 	ownerSpoof := state.OwnerID("ownerX")
464: 	sessionID := state.NewSessionID()
465: 
466: 	// Crafted snapshot with session owner != snap.Owner
467: 	spoofedSession := state.LocalSessionRecord{
468: 		ID:    sessionID,
469: 		Owner: ownerSpoof, // SPOOF: different from snapshot owner
470: 		Ref:   state.SessionRef{Owner: ownerSpoof, Session: sessionID},
471: 	}
472: 	mgr.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{
473: 		Owner:    owner,
474: 		Revision: 1,
475: 		Sessions: []state.LocalSessionRecord{spoofedSession},
476: 	})
477: 
478: 	// Snapshot must be rejected; no cache entry should exist
479: 	if _, ok := mgr.RemoteCatalogSnapshot(owner); ok {
480: 		t.Fatal("spoofed session owner snapshot was accepted")
481: 	}
482: }
