535: // TestRemoteSnapshot_OutOfOrderDelivery proves that revisions delivered
536: // out of order within one connection (10, 8, 11) result in 11 being accepted
537: // as authoritative, never regressing to 8.
538: func TestRemoteSnapshot_OutOfOrderDelivery(t *testing.T) {
539: 	mgr := makeV2Manager(t)
540: 	peerID := "peer-a"
541: 	owner := state.OwnerID("owner1")
542: 
543: 	// Deliver revision 10
544: 	s1 := state.LocalSessionRecord{ID: "s1", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s1"}}
545: 	mgr.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{
546: 		Owner:    owner,
547: 		Revision: 10,
548: 		Sessions: []state.LocalSessionRecord{s1},
549: 	})
550: 	snap, _ := mgr.RemoteCatalogSnapshot(owner)
551: 	if len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s1" {
552: 		t.Fatalf("expected s1 in cache after rev 10")
553: 	}
554: 
555: 	// Deliver revision 8 (stale, out of order) -> must be rejected
556: 	s2 := state.LocalSessionRecord{ID: "s2", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s2"}}
557: 	mgr.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{
558: 		Owner:    owner,
559: 		Revision: 8,
560: 		Sessions: []state.LocalSessionRecord{s2},
561: 	})
562: 	snap, _ = mgr.RemoteCatalogSnapshot(owner)
563: 	if len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s1" {
564: 		t.Fatalf("stale revision 8 regressed cache: expected s1, got %+v", snap.Sessions)
565: 	}
566: 
567: 	// Deliver revision 11 (newer) -> must be accepted
568: 	s3 := state.LocalSessionRecord{ID: "s3", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s3"}}
569: 	mgr.UpdateRemoteCatalog(peerID, state.OwnerCatalogSnapshot{
570: 		Owner:    owner,
571: 		Revision: 11,
572: 		Sessions: []state.LocalSessionRecord{s3},
573: 	})
574: 	snap, _ = mgr.RemoteCatalogSnapshot(owner)
575: 	if len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s3" {
576: 		t.Fatalf("revision 11 not accepted: got %+v", snap.Sessions)
577: 	}
578: }
