580: // TestRemoteSnapshot_NewGenerationAcceptsLowerRevision proves that a new peer
581: // connection (generation) allows the same revision counter to be re-accepted,
582: // and even lower revisions if they are authoritative from a fresh connection.
583: func TestRemoteSnapshot_NewGenerationAcceptsLowerRevision(t *testing.T) {
584: 	mgr := makeV2Manager(t)
585: 	remoteID, err := identity.Generate("remote")
586: 	if err != nil {
587: 		t.Fatal(err)
588: 	}
589: 	fp := remoteID.Fingerprint()
590: 	owner := state.OwnerID(fp)
591: 
592: 	// First connection sends revision 100
593: 	conn1 := NewPeerConnection(fp, 64)
594: 	mgr.RegisterPeer(fp, "remote", remoteID.PublicKey, conn1)
595: 	s1 := state.LocalSessionRecord{ID: "s1", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s1"}}
596: 	mgr.UpdateRemoteCatalog(fp, state.OwnerCatalogSnapshot{
597: 		Owner:    owner,
598: 		Revision: 100,
599: 		Sessions: []state.LocalSessionRecord{s1},
600: 	})
601: 
602: 	// Reconnect with a new connection
603: 	conn2 := NewPeerConnection(fp, 64)
604: 	mgr.RegisterPeer(fp, "remote", remoteID.PublicKey, conn2)
605: 
606: 	// Fresh connection sends revision 5 (lower than 100) -> should be accepted
607: 	s2 := state.LocalSessionRecord{ID: "s2", Owner: owner, Ref: state.SessionRef{Owner: owner, Session: "s2"}}
608: 	mgr.UpdateRemoteCatalog(fp, state.OwnerCatalogSnapshot{
609: 		Owner:    owner,
610: 		Revision: 5,
611: 		Sessions: []state.LocalSessionRecord{s2},
612: 	})
613: 
614: 	snap, ok := mgr.RemoteCatalogSnapshot(owner)
615: 	if !ok || len(snap.Sessions) != 1 || snap.Sessions[0].ID != "s2" {
616: 		t.Fatalf("new generation should accept lower revision, got %+v (ok=%v)", snap.Sessions, ok)
617: 	}
