  22: const (
  23: 	// OfflineTimeout is how long to keep an offline peer's sessions visible
  24: 	OfflineTimeout = 5 * time.Minute
  25: )
  26: 
  27: // HostState holds all known state for a single peer
  28: type HostState struct {
  29: 	ID         string // public key fingerprint
  30: 	Name       string
  31: 	Version    string
  32: 	PublicKey  string
  33: 	Address    string // network address (empty for local)
  34: 	Sessions   []*model.Session
  35: 	Stats      map[string]interface{}
  36: 	Activity   []*activity.Snapshot
  37: 	ToolEvents []*toolevents.Event
  38: 	Connected  bool
  39: 	LastSeen   time.Time
  40: 	Conn       *PeerConnection // nil for local host
  41: }
  42: 
  43: // wireFrame is a pre-serialized WebSocket frame ready for the wire. Marshaling
  44: // happens in the producer goroutine (off the single writer) so the writer only
  45: // does the syscall.
  46: type wireFrame struct {
  47: 	data []byte
  48: }
  49: 
  50: // Queue depths. The hi lane carries interactive PTY traffic (keystrokes,
  51: // output, resize) and is deep so a burst of output never starves input. The
  52: // lo lane carries bulky, latency-tolerant control plane (state snapshots,
  53: // stats, activity data, tool events).
  54: const (
  55: 	hiQueueDepth = 1024
  56: 	loQueueDepth = 128
  57: )
  58: 
  59: // PeerConnection wraps a control WebSocket to a peer. Sends are gated behind
  60: // Enqueue*/Close so concurrent producers cannot race the close, and split into
  61: // two priority lanes so bulky control-plane messages never block PTY frames
  62: // (head-of-line blocking was the dominant source of typing jitter).
  63: type PeerConnection struct {
  64: 	HostID string
  65: 	Role   Role
  66: 	Caps   []string
  67: 
  68: 	mu     sync.Mutex
  69: 	hi     chan wireFrame
  70: 	lo     chan wireFrame
  71: 	done   chan struct{}
  72: 	closed bool
  73: 
  74: 	// v2 coalescing snapshot slots and reliable command queue.
  75: 	catalogSlot   *snapshotSlot
  76: 	workspaceSlot *snapshotSlot
  77: 	cmdQueue      *reliableCommandQueue
  78: }
  79: 
  80: // NewPeerConnection constructs a PeerConnection with buffered priority lanes.
  81: // bufSize seeds the low-priority lane; the hi lane is fixed-deep.
  82: func NewPeerConnection(hostID string, bufSize int) *PeerConnection {
  83: 	if bufSize < loQueueDepth {
  84: 		bufSize = loQueueDepth
  85: 	}
  86: 	return &PeerConnection{
  87: 		HostID: hostID,
  88: 		hi:     make(chan wireFrame, hiQueueDepth),
  89: 		lo:     make(chan wireFrame, bufSize),
  90: 		done:   make(chan struct{}),
  91: 	}
  92: }
  93: 
  94: // initV2Lazy lazily initializes v2 slots/queue. It is safe to call multiple
  95: // times because a real PeerConnection is created once per connection.
  96: func (pc *PeerConnection) initV2Lazy() {
  97: 	pc.mu.Lock()
  98: 	defer pc.mu.Unlock()
  99: 	if pc.catalogSlot == nil {
 100: 		pc.catalogSlot = newSnapshotSlot()
 101: 		pc.workspaceSlot = newSnapshotSlot()
 102: 		pc.cmdQueue = newReliableCommandQueue(32)
 103: 	}
 104: }
 105: 
 106: // Done returns a channel that is closed when the connection is closed. Lets
 107: // consumers (e.g. the browser-input pump) react when the underlying peer link
 108: // dies and tear down dependent state instead of silently dropping messages.
 109: func (pc *PeerConnection) Done() <-chan struct{} {
 110: 	return pc.done
 111: }
 112: 
 113: // HasCapability reports whether the peer advertised a specific capability
 114: // during the hello handshake.
 115: func (pc *PeerConnection) HasCapability(cap string) bool {
 116: 	for _, c := range pc.Caps {
 117: 		if c == cap {
 118: 			return true
 119: 		}
 120: 	}
 121: 	return false
 122: }
 123: 
 124: // HiLane / LoLane expose the lanes to the writer goroutine for priority drain.
 125: func (pc *PeerConnection) HiLane() <-chan wireFrame { return pc.hi }
 126: func (pc *PeerConnection) LoLane() <-chan wireFrame { return pc.lo }
 127: 
 128: func (pc *PeerConnection) enqueue(ch chan wireFrame, f wireFrame) bool {
 129: 	pc.mu.Lock()
 130: 	defer pc.mu.Unlock()
 131: 	if pc.closed {
 132: 		return false
 133: 	}
 134: 	select {
 135: 	case ch <- f:
 136: 		return true
 137: 	default:
 138: 		return false
 139: 	}
 140: }
 141: 
 142: // Enqueue best-effort queues a control-plane JSON message on the low-priority
 143: // lane. Returns false if the connection was closed or the lane is full.
 144: func (pc *PeerConnection) Enqueue(msg *Message) bool {
 145: 	data, err := json.Marshal(msg)
 146: 	if err != nil {
 147: 		return false
 148: 	}
 149: 	return pc.enqueue(pc.lo, wireFrame{data: data})
 150: }
 151: 
 152: // EnqueueHi best-effort queues a small interactive JSON message (e.g. PTY
 153: // resize/control) on the high-priority lane.
 154: func (pc *PeerConnection) EnqueueHi(msg *Message) bool {
 155: 	data, err := json.Marshal(msg)
 156: 	if err != nil {
 157: 		return false
 158: 	}
 159: 	return pc.enqueue(pc.hi, wireFrame{data: data})
 160: }
 161: 
 162: // Close marks the connection closed. Idempotent. The lanes are never closed
 163: // (producers gate on the closed flag under mu), so there is no send-on-closed
 164: // race; the writer goroutine exits via Done.
 165: func (pc *PeerConnection) Close() {
 166: 	pc.mu.Lock()
 167: 	defer pc.mu.Unlock()
 168: 	if pc.closed {
 169: 		return
 170: 	}
 171: 	pc.closed = true
 172: 	close(pc.done)
 173: }
 174: 
 175: // Manager aggregates state from local sessions and remote peers
 176: type Manager struct {
 177: 	mu    sync.RWMutex
 178: 	hosts map[string]*HostState // keyed by peer fingerprint
 179: 
 180: 	localID   string // this node's fingerprint
 181: 	localName string
 182: 	identity  *identity.Identity
 183: 	peerStore *identity.PeerStore
 184: 	localMgr  *state.Manager
 185: 
 186: 	// Subscribers for state changes (browser WebSocket hub subscribes here)
 187: 	subMu       sync.RWMutex
 188: 	subscribers []chan state.StateEvent
 189: 
 190: 	// v2 remote catalog caches, keyed by owner ID. They survive reconnects
 191: 	// until explicitly forgotten.
 192: 	catalogMu      sync.RWMutex
 193: 	remoteCatalogs map[state.OwnerID]remoteCatalogCache
 194: 
 195: 	// remoteRevs tracks the last-accepted snapshot revision per peer for the
 196: 	// peer's current connection. A new connection (re-registration) resets the
 197: 	// baseline so a restarted peer with a fresh revision counter is accepted;
 198: 	// within one connection, non-increasing revisions (stale or delayed
 199: 	// snapshots) are rejected to stop cache regression. Guarded by catalogMu.
 200: 	remoteRevs map[string]*remoteRevisionState
 201: 
 202: 	// ownerBinding enforces one owner per peer and one peer per owner so a
 203: 	// peer cannot publish state under another peer's established owner.
 204: 	// Guarded by catalogMu. Owner is a v2 OwnerID (random base32), which is
 205: 	// distinct from the peer fingerprint.
 206: 	peerOwner map[string]state.OwnerID
 207: 	ownerPeer map[state.OwnerID]string
 208: 
 209: 	// v2 reliable command waiters.
 210: 	cmdMu          sync.Mutex
 211: 	commandWaiters map[string]*commandWaiter
 212: 
 213: 	// remoteStore persists remote catalog caches across restarts.
 214: 	remoteStore *state.Store
 215: 
 216: 	// v2RemoteCreate runs local owner-side remote-create sagas and resumes
 217: 	// pending creates after restart.
 218: 	v2RemoteCreate *state.RemoteCreateCoordinator
 219: }
 220: 
 221: // remoteCatalogCache is an immutable, owner-keyed view received from a peer.
 222: type remoteCatalogCache struct {
 223: 	Owner        state.OwnerID
 224: 	PeerID       string
 225: 	Snapshot     state.OwnerCatalogSnapshot
 226: 	Workspace    *state.WorkspaceRecord
 227: 	ReceivedAt   time.Time
 228: 	CatalogRev   int64
 229: 	WorkspaceRev int64
 230: }
 231: 
 232: // remoteRevisionState is the per-peer, per-connection revision baseline for
 233: // v2 snapshot streams. -1 means "no baseline yet" (fresh connection).
 234: type remoteRevisionState struct {
 235: 	catalog   int64
 236: 	workspace map[state.LayoutID]int64
 237: }
 238: 
 239: // NewManager creates a new peer manager
 240: func NewManager(id *identity.Identity, peerStore *identity.PeerStore, localMgr *state.Manager) *Manager {
 241: 	m := &Manager{
 242: 		hosts:     make(map[string]*HostState),
 243: 		localID:   id.Fingerprint(),
 244: 		localName: id.Name,
 245: 		identity:  id,
 246: 		peerStore: peerStore,
 247: 		localMgr:  localMgr,
 248: 	}
 249: 
 250: 	// Register local host
 251: 	m.hosts[m.localID] = &HostState{
 252: 		ID:        m.localID,
 253: 		Name:      id.Name,
 254: 		Version:   common.VERSION,
 255: 		PublicKey: id.PublicKey,
 256: 		Connected: true,
 257: 		LastSeen:  time.Now(),
 258: 	}
 259: 
 260: 	m.remoteCatalogs = make(map[state.OwnerID]remoteCatalogCache)
 261: 	m.remoteRevs = make(map[string]*remoteRevisionState)
 262: 	m.peerOwner = make(map[string]state.OwnerID)
 263: 	m.ownerPeer = make(map[state.OwnerID]string)
 264: 	m.commandWaiters = make(map[string]*commandWaiter)
 265: 
 266: 	return m
 267: }
 268: 
 269: // updateLocalStats collects system stats and process counts for the local host
 270: func (m *Manager) updateLocalStats() {
 271: 	s := stats.SystemStats()
 272: 	sessions := m.localMgr.GetSessions()
 273: 	s["processes"] = stats.ProcessCountsFromSessions(sessions)
 274: 	m.UpdatePeerStats(m.localID, s)
 275: }
 276: 
 277: // Run starts forwarding local state events to peer manager subscribers
 278: // and pruning offline peers. Blocks until ctx is cancelled.
 279: func (m *Manager) Run(ctx context.Context) {
 280: 	// Forward local state events
 281: 	localCh := m.localMgr.Subscribe()
 282: 	defer m.localMgr.Unsubscribe(localCh)
 283: 
 284: 	pruneTimer := time.NewTicker(30 * time.Second)
 285: 	defer pruneTimer.Stop()
 286: 
 287: 	statsTimer := time.NewTicker(30 * time.Second)
 288: 	defer statsTimer.Stop()
 289: 
 290: 	// Collect initial stats
 291: 	m.updateLocalStats()
 292: 
 293: 	for {
 294: 		select {
 295: 		case evt, ok := <-localCh:
 296: 			if !ok {
 297: 				return
 298: 			}
 299: 			// Stamp with local host info
 300: 			evt.Host = m.localID
 301: 			evt.HostName = m.localName
 302: 
 303: 			// Update local sessions cache
 304: 			m.mu.Lock()
 305: 			if h, ok := m.hosts[m.localID]; ok {
 306: 				h.Sessions = m.localMgr.GetSessions()
 307: 				h.LastSeen = time.Now()
 308: 			}
 309: 			m.mu.Unlock()
 310: 
 311: 			m.broadcast(evt)
 312: 
 313: 		case <-statsTimer.C:
 314: 			m.updateLocalStats()
 315: 
 316: 		case <-pruneTimer.C:
 317: 			m.pruneOffline()
 318: 
 319: 		case <-ctx.Done():
 320: 			return
 321: 		}
 322: 	}
 323: }
 324: 
 325: // Subscribe returns a channel that receives state events from all hosts
 326: func (m *Manager) Subscribe() chan state.StateEvent {
 327: 	ch := make(chan state.StateEvent, 64)
 328: 	m.subMu.Lock()
 329: 	m.subscribers = append(m.subscribers, ch)
 330: 	m.subMu.Unlock()
 331: 	return ch
 332: }
 333: 
 334: // Unsubscribe removes a subscriber channel
 335: func (m *Manager) Unsubscribe(ch chan state.StateEvent) {
 336: 	m.subMu.Lock()
 337: 	defer m.subMu.Unlock()
 338: 	for i, sub := range m.subscribers {
 339: 		if sub == ch {
 340: 			m.subscribers = append(m.subscribers[:i], m.subscribers[i+1:]...)
 341: 			close(ch)
 342: 			return
 343: 		}
 344: 	}
 345: }
 346: 
 347: // broadcast sends an event to all subscribers
 348: func (m *Manager) broadcast(evt state.StateEvent) {
 349: 	m.subMu.RLock()
 350: 	defer m.subMu.RUnlock()
 351: 	for _, ch := range m.subscribers {
 352: 		select {
 353: 		case ch <- evt:
 354: 		default:
 355: 		}
 356: 	}
 357: }
 358: 
 359: // GetAllSessions returns sessions from all hosts, with host fields stamped.
 360: // The returned slice and session values are copies so callers cannot mutate
 361: // internal manager state.
 362: func (m *Manager) GetAllSessions() []*model.Session {
 363: 	m.mu.RLock()
 364: 	defer m.mu.RUnlock()
 365: 
 366: 	var all []*model.Session
 367: 	for _, h := range m.hosts {
 368: 		for _, s := range h.Sessions {
 369: 			copyS := copySession(s)
 370: 			copyS.Host = h.ID
 371: 			copyS.HostName = h.Name
 372: 			copyS.HostOnline = h.Connected
 373: 			all = append(all, copyS)
 374: 		}
 375: 	}
 376: 	return all
 377: }
 378: 
 379: func copySession(s *model.Session) *model.Session {
 380: 	if s == nil {
 381: 		return nil
 382: 	}
 383: 	c := *s
 384: 	if len(s.Windows) > 0 {
 385: 		c.Windows = make([]*model.Window, 0, len(s.Windows))
 386: 		for _, w := range s.Windows {
 387: 			if w == nil {
 388: 				c.Windows = append(c.Windows, nil)
 389: 				continue
 390: 			}
 391: 			cw := *w
 392: 			if len(w.Panes) > 0 {
 393: 				cw.Panes = make([]*model.Pane, 0, len(w.Panes))
 394: 				for _, p := range w.Panes {
 395: 					if p == nil {
 396: 						cw.Panes = append(cw.Panes, nil)
 397: 						continue
 398: 					}
 399: 					cp := *p
 400: 					cw.Panes = append(cw.Panes, &cp)
 401: 				}
 402: 			}
 403: 			c.Windows = append(c.Windows, &cw)
 404: 		}
 405: 	}
 406: 	return &c
 407: }
