 409: // GetLocalSessions returns only this node's sessions
 410: func (m *Manager) GetLocalSessions() []*model.Session {
 411: 	return m.localMgr.GetSessions()
 412: }
 413: 
 414: // GetHosts returns info about all known hosts. Session slices are copied so
 415: // callers cannot mutate internal state.
 416: func (m *Manager) GetHosts() []HostInfo {
 417: 	m.mu.RLock()
 418: 	defer m.mu.RUnlock()
 419: 
 420: 	hosts := make([]HostInfo, 0, len(m.hosts))
 421: 	for _, h := range m.hosts {
 422: 		sessions := make([]*model.Session, len(h.Sessions))
 423: 		for i, s := range h.Sessions {
 424: 			sessions[i] = copySession(s)
 425: 		}
 426: 		hosts = append(hosts, HostInfo{
 427: 			ID:       h.ID,
 428: 			Name:     h.Name,
 429: 			Version:  h.Version,
 430: 			Local:    h.ID == m.localID,
 431: 			Online:   h.Connected,
 432: 			Address:  h.Address,
 433: 			Sessions: sessions,
 434: 			Activity: h.Activity,
 435: 			Stats:    h.Stats,
 436: 			LastSeen: h.LastSeen,
 437: 		})
 438: 	}
 439: 	return hosts
 440: }
 441: 
 442: // GetHostsForPeer returns only the local host info, used to push to a connected
 443: // peer without leaking other peers (no transitivity in phase 1).
 444: func (m *Manager) GetHostsForPeer(remotePeerID string) []HostInfo {
 445: 	m.mu.RLock()
 446: 	defer m.mu.RUnlock()
 447: 
 448: 	h, ok := m.hosts[m.localID]
 449: 	if !ok {
 450: 		return nil
 451: 	}
 452: 	return []HostInfo{{
 453: 		ID:       h.ID,
 454: 		Name:     h.Name,
 455: 		Version:  h.Version,
 456: 		Local:    true,
 457: 		Online:   h.Connected,
 458: 		Address:  h.Address,
 459: 		Sessions: h.Sessions,
 460: 		Activity: h.Activity,
 461: 		Stats:    h.Stats,
 462: 		LastSeen: h.LastSeen,
 463: 	}}
 464: }
