 491: // SetRemoteStore wires the app-state store used to persist remote catalog
 492: // caches. It is safe to call before any peer connects.
 493: func (m *Manager) SetRemoteStore(store *state.Store) {
 494: 	m.catalogMu.Lock()
 495: 	defer m.catalogMu.Unlock()
 496: 	m.remoteStore = store
