 498: 
 499: // RegisterPeer registers a newly connected peer
 500: func (m *Manager) RegisterPeer(id, name, publicKey string, conn *PeerConnection) {
 501: 	m.RegisterPeerWithAddress(id, name, publicKey, "", conn)
 502: }
 503: 
 504: // RegisterPeerWithAddress registers a newly connected peer with its address.
 505: func (m *Manager) RegisterPeerWithAddress(id, name, publicKey, address string, conn *PeerConnection) {
 506: 	m.mu.Lock()
 507: 	m.hosts[id] = &HostState{
 508: 		ID:        id,
 509: 		Name:      name,
 510: 		PublicKey: publicKey,
 511: 		Address:   address,
 512: 		Connected: true,
 513: 		LastSeen:  time.Now(),
 514: 		Conn:      conn,
 515: 	}
 516: 	m.mu.Unlock()
 517: 
 518: 	// A new connection is a new snapshot-stream generation: reset the
 519: 	// revision baseline so a restarted peer's re-emitted snapshots are
 520: 	// accepted even though their revisions are lower than the last ones seen
 521: 	// on the previous connection.
 522: 	m.resetRemoteRevisions(id)
 523: 
 524: 	m.broadcast(state.StateEvent{
 525: 		Type:     "peer-connected",
 526: 		Host:     id,
 527: 		HostName: name,
 528: 	})
 529: 
 530: 	logrus.WithFields(logrus.Fields{
 531: 		"peer": name,
 532: 		"id":   id,
 533: 	}).Info("peer connected")
 534: }
 535: 
 536: // TryRegisterPeer atomically registers a peer iff no live connection exists
 537: // for the same fingerprint. Returns true on success. Used by session.runSession
 538: // to close the simultaneous-initiate race window.
 539: func (m *Manager) TryRegisterPeer(id, name, publicKey, address string, conn *PeerConnection) bool {
 540: 	m.mu.Lock()
 541: 	if h, ok := m.hosts[id]; ok && h.Conn != nil {
 542: 		m.mu.Unlock()
 543: 		return false
 544: 	}
 545: 	m.hosts[id] = &HostState{
 546: 		ID:        id,
 547: 		Name:      name,
 548: 		PublicKey: publicKey,
 549: 		Address:   address,
 550: 		Connected: true,
 551: 		LastSeen:  time.Now(),
 552: 		Conn:      conn,
 553: 	}
 554: 	m.mu.Unlock()
 555: 
 556: 	m.resetRemoteRevisions(id)
 557: 
 558: 	m.broadcast(state.StateEvent{
 559: 		Type:     "peer-connected",
 560: 		Host:     id,
 561: 		HostName: name,
 562: 	})
 563: 
 564: 	logrus.WithFields(logrus.Fields{
 565: 		"peer": name,
 566: 		"id":   id,
 567: 	}).Info("peer connected")
 568: 	return true
 569: }
 570: 
 571: // UnregisterPeer marks the peer offline unconditionally. Prefer
 572: // UnregisterPeerConn to prevent a stale connection from unregistering a
 573: // replacement.
 574: func (m *Manager) UnregisterPeer(id string) {
 575: 	m.UnregisterPeerConn(id, nil)
 576: }
 577: 
 578: // UnregisterPeerConn marks the peer offline only if conn is the currently
 579: // registered connection. A nil conn acts as an unconditional unregister.
 580: func (m *Manager) UnregisterPeerConn(id string, conn *PeerConnection) {
 581: 	m.mu.Lock()
 582: 	h, ok := m.hosts[id]
 583: 	if ok {
 584: 		if conn != nil && h.Conn != conn {
 585: 			m.mu.Unlock()
 586: 			logrus.WithFields(logrus.Fields{
 587: 				"peer": h.Name,
 588: 				"id":   id,
 589: 			}).Debug("stale connection ignored during unregister")
 590: 			return
 591: 		}
 592: 		h.Connected = false
 593: 		h.Conn = nil
 594: 		h.LastSeen = time.Now()
 595: 	}
 596: 	m.mu.Unlock()
 597: 
 598: 	if ok {
 599: 		m.broadcast(state.StateEvent{
 600: 			Type:     "peer-disconnected",
 601: 			Host:     id,
 602: 			HostName: h.Name,
 603: 		})
 604: 
 605: 		logrus.WithFields(logrus.Fields{
 606: 			"peer": h.Name,
 607: 			"id":   id,
 608: 		}).Info("peer disconnected")
 609: 	}
 610: }
 611: 
 612: // RemoveHost fully removes a host from the aggregated state (used on forget,
 613: // where we must not keep the peer's sessions lingering until prune).
 614: func (m *Manager) RemoveHost(id string) {
 615: 	if id == m.localID {
 616: 		return
 617: 	}
 618: 	m.mu.Lock()
 619: 	h, ok := m.hosts[id]
 620: 	if ok {
 621: 		delete(m.hosts, id)
 622: 	}
 623: 	m.mu.Unlock()
 624: 
 625: 	if ok {
 626: 		m.forgetRemoteCatalogsForPeer(id)
 627: 		m.broadcast(state.StateEvent{
 628: 			Type:     "peer-disconnected",
 629: 			Host:     id,
 630: 			HostName: h.Name,
 631: 		})
 632: 		logrus.WithFields(logrus.Fields{
 633: 			"peer": h.Name,
 634: 			"id":   id,
 635: 		}).Info("host removed")
 636: 	}
 637: }
 638: 
 639: // validateCatalogOwnership checks that all sessions and layouts in the snapshot
 640: // have their Owner field matching the snapshot's top-level owner. Returns false
 641: // and logs a warning if any embedded owner differs.
 642: func validateCatalogOwnership(peerID string, snap state.OwnerCatalogSnapshot) bool {
 643: 	for _, sess := range snap.Sessions {
 644: 		if sess.Owner != snap.Owner {
 645: 			logrus.WithFields(logrus.Fields{
 646: 				"peer": peerID,
 647: 				"owner": string(snap.Owner),
 648: 				"session_id": string(sess.ID),
 649: 				"session_owner": string(sess.Owner),
 650: 			}).Warn("dropping v2 snapshot: embedded session owner mismatch")
 651: 			return false
 652: 		}
 653: 	}
 654: 	for _, layout := range snap.Layouts {
 655: 		if layout.Owner != snap.Owner {
 656: 			logrus.WithFields(logrus.Fields{
 657: 				"peer": peerID,
 658: 				"owner": string(snap.Owner),
 659: 				"layout_id": string(layout.ID),
 660: 				"layout_owner": string(layout.Owner),
 661: 			}).Warn("dropping v2 snapshot: embedded layout owner mismatch")
 662: 			return false
 663: 		}
 664: 	}
 665: 	return true
 666: }
 667: 
 668: // validateWorkspaceTreeOwnership recursively checks that all leaf SessionRefs in
 669: // the tree have owner matching rec.Owner. Returns false and logs a warning if
 670: // any leaf ref differs.
 671: func validateWorkspaceTreeOwnership(peerID string, rec state.WorkspaceRecord) bool {
 672: 	var checkNode func(*state.PaneNode) bool
 673: 	checkNode = func(node *state.PaneNode) bool {
 674: 		if node == nil {
 675: 			return true
 676: 		}
 677: 		if node.IsLeaf() {
 678: 			if node.Ref != nil && node.Ref.Owner != rec.Owner {
 679: 				logrus.WithFields(logrus.Fields{
 680: 					"peer": peerID,
 681: 					"owner": string(rec.Owner),
 682: 					"layout_id": string(rec.ID),
 683: 					"ref_owner": string(node.Ref.Owner),
 684: 				}).Warn("dropping v2 snapshot: embedded leaf owner mismatch")
 685: 				return false
 686: 			}
 687: 			return true
 688: 		}
 689: 		if node.IsSplit() {
 690: 			if !checkNode(node.First) || !checkNode(node.Second) {
 691: 				return false
 692: 			}
 693: 		}
 694: 		return true
 695: 	}
 696: 	return checkNode(&rec.Tree)
 697: }
 698: 
 699: // bindRemoteOwner enforces the ownership binding: one owner per peer and one
 700: // peer per owner. The first snapshot a peer publishes establishes its sole
 701: // owner; a later snapshot from the same peer under a different owner, or a
 702: // second peer claiming an already-bound owner, is a spoof and is dropped.
 703: // Caller must hold catalogMu. The v2 catalog Owner is a random base32 id, NOT
 704: // the peer fingerprint, so an explicit cross-peer binding map is the sound
 705: // integrity mechanism here.
 706: func (m *Manager) bindRemoteOwner(peerID string, owner state.OwnerID) bool {
 707: 	if peerID == "" || owner == "" {
 708: 		return false
 709: 	}
 710: 	if p, ok := m.ownerPeer[owner]; ok && p != peerID {
 711: 		logrus.WithFields(logrus.Fields{"peer": peerID, "owner": string(owner), "boundPeer": p}).Warn("dropping v2 snapshot: owner already bound to another peer")
 712: 		return false
 713: 	}
 714: 	if o, ok := m.peerOwner[peerID]; ok && o != owner {
 715: 		logrus.WithFields(logrus.Fields{"peer": peerID, "owner": string(owner), "boundOwner": string(o)}).Warn("dropping v2 snapshot: peer switched owners")
 716: 		return false
 717: 	}
 718: 	m.peerOwner[peerID] = owner
 719: 	m.ownerPeer[owner] = peerID
 720: 	return true
 721: }
 722: 
 723: // UpdateRemoteCatalog replaces the cached catalog for the snapshot's owner.
 724: // The previous cache (if any) is overwritten, not merged. The owner must be
 725: // the peer's bound owner and the revision must be increasing within the
 726: // peer's current connection (stale/delayed snapshots are rejected). All
 727: // embedded session and layout owners must match the snapshot's owner. If a
 728: // remote store is wired, the complete set of accepted remote catalogs is
 729: // persisted.
 730: func (m *Manager) UpdateRemoteCatalog(peerID string, snap state.OwnerCatalogSnapshot) {
 731: 	if !validateCatalogOwnership(peerID, snap) {
 732: 		return
 733: 	}
 734: 	m.catalogMu.Lock()
 735: 	if !m.bindRemoteOwner(peerID, snap.Owner) {
 736: 		m.catalogMu.Unlock()
 737: 		return
 738: 	}
 739: 	rs := m.remoteRevs[peerID]
 740: 	if rs == nil {
 741: 		rs = &remoteRevisionState{catalog: -1}
 742: 		m.remoteRevs[peerID] = rs
 743: 	}
 744: 	if rs.catalog >= 0 && snap.Revision <= rs.catalog {
 745: 		m.catalogMu.Unlock()
 746: 		logrus.WithFields(logrus.Fields{"peer": peerID, "rev": snap.Revision, "last": rs.catalog}).Debug("dropping stale v2 catalog snapshot")
 747: 		return
 748: 	}
 749: 	rs.catalog = snap.Revision
 750: 	m.remoteCatalogs[snap.Owner] = remoteCatalogCache{
 751: 		Owner:      snap.Owner,
 752: 		PeerID:     peerID,
 753: 		Snapshot:   snap,
 754: 		ReceivedAt: time.Now(),
 755: 		CatalogRev: snap.Revision,
 756: 	}
 757: 	m.catalogMu.Unlock()
 758: 	m.persistRemoteCatalogs()
 759: }
 760: 
 761: // UpdateRemoteWorkspace replaces the cached workspace for owner. The owner
 762: // must be the peer's bound owner, and the workspace revision must be
 763: // increasing within the current connection (keyed per layout id). All
 764: // embedded leaf SessionRefs in the tree must have owner matching rec.Owner.
 765: func (m *Manager) UpdateRemoteWorkspace(peerID string, rec state.WorkspaceRecord) {
 766: 	if !validateWorkspaceTreeOwnership(peerID, rec) {
 767: 		return
 768: 	}
 769: 	m.catalogMu.Lock()
 770: 	if !m.bindRemoteOwner(peerID, rec.Owner) {
 771: 		m.catalogMu.Unlock()
 772: 		return
 773: 	}
 774: 	rs := m.remoteRevs[peerID]
 775: 	if rs == nil {
 776: 		rs = &remoteRevisionState{catalog: -1}
 777: 		m.remoteRevs[peerID] = rs
 778: 	}
 779: 	if rs.workspace == nil {
 780: 		rs.workspace = make(map[state.LayoutID]int64)
 781: 	}
 782: 	if last, seen := rs.workspace[rec.ID]; seen && rec.Revision <= last {
 783: 		m.catalogMu.Unlock()
 784: 		logrus.WithFields(logrus.Fields{"peer": peerID, "layout": string(rec.ID), "rev": rec.Revision, "last": last}).Debug("dropping stale v2 workspace snapshot")
 785: 		return
 786: 	}
 787: 	rs.workspace[rec.ID] = rec.Revision
 788: 	cache := m.remoteCatalogs[rec.Owner]
 789: 	cache.Owner = rec.Owner
 790: 	cache.PeerID = peerID
 791: 	cache.Workspace = &rec
 792: 	cache.ReceivedAt = time.Now()
 793: 	cache.WorkspaceRev = rec.Revision
 794: 	m.remoteCatalogs[rec.Owner] = cache
 795: 	m.catalogMu.Unlock()
 796: 	m.persistRemoteCatalogs()
 797: }
 798: 
 799: // RemoteCatalogSnapshot returns the latest cached catalog for owner, if any.
 800: func (m *Manager) RemoteCatalogSnapshot(owner state.OwnerID) (state.OwnerCatalogSnapshot, bool) {
 801: 	m.catalogMu.RLock()
 802: 	defer m.catalogMu.RUnlock()
 803: 	c, ok := m.remoteCatalogs[owner]
 804: 	if !ok {
 805: 		return state.OwnerCatalogSnapshot{}, false
 806: 	}
 807: 	return cloneOwnerCatalogSnapshot(c.Snapshot), true
 808: }
 809: 
 810: // RemoteWorkspaceSnapshot returns the latest cached workspace for owner, if any.
 811: func (m *Manager) RemoteWorkspaceSnapshot(owner state.OwnerID) (*state.WorkspaceRecord, bool) {
 812: 	m.catalogMu.RLock()
 813: 	defer m.catalogMu.RUnlock()
 814: 	c, ok := m.remoteCatalogs[owner]
 815: 	if !ok || c.Workspace == nil {
 816: 		return nil, false
 817: 	}
 818: 	w := *c.Workspace
 819: 	return &w, true
 820: }
 821: 
 822: // ForgetRemoteCatalog removes the cached catalog and workspace for owner.
 823: func (m *Manager) ForgetRemoteCatalog(owner state.OwnerID) {
 824: 	m.catalogMu.Lock()
 825: 	delete(m.remoteCatalogs, owner)
 826: 	m.catalogMu.Unlock()
 827: 	m.persistRemoteCatalogs()
 828: }
 829: 
 830: // SetRemoteCreateCoordinator wires the v2 owner-side remote create coordinator.
 831: func (m *Manager) SetRemoteCreateCoordinator(c *state.RemoteCreateCoordinator) {
 832: 	m.v2RemoteCreate = c
 833: }
 834: 
 835: // WorkspaceAuthority returns the owning owner for layout and, when the owner is
 836: // remote, the peer ID that last advertised it. The empty peerID means this node
 837: // is the authority.
 838: func (m *Manager) WorkspaceAuthority(layout state.LayoutID) (state.OwnerID, string, error) {
 839: 	if cat := m.localMgr.V2Catalog(); cat != nil {
 840: 		if rec, ok := cat.Layout(layout); ok {
 841: 			return rec.Owner, "", nil
 842: 		}
 843: 	}
 844: 	m.catalogMu.RLock()
 845: 	defer m.catalogMu.RUnlock()
 846: 	for owner, cache := range m.remoteCatalogs {
 847: 		for _, l := range cache.Snapshot.Layouts {
 848: 			if l.ID == layout {
 849: 				return owner, cache.PeerID, nil
 850: 			}
 851: 		}
 852: 		if cache.Workspace != nil && cache.Workspace.ID == layout {
 853: 			return owner, cache.PeerID, nil
 854: 		}
 855: 	}
 856: 	return "", "", state.StateError{Code: state.ErrUnknownLayout, Field: "layout", Detail: fmt.Sprintf("workspace authority not found for layout %q", layout)}
 857: }
 858: 
 859: // IsWorkspaceOwnerOnline reports whether owner is reachable for v2 commands.
 860: func (m *Manager) IsWorkspaceOwnerOnline(owner state.OwnerID) bool {
 861: 	if owner == state.OwnerID(m.localID) {
 862: 		return true
 863: 	}
 864: 	peerID := m.peerIDForOwner(owner)
 865: 	if peerID == "" {
 866: 		return false
 867: 	}
 868: 	pc := m.GetPeerConnection(peerID)
 869: 	return pc != nil && pc.HasV2()
 870: }
 871: 
 872: // ProxyWorkspaceCommand routes a workspace command to the layout's owner.
 873: // Local authority applies directly; remote authority is sent over the v2
 874: // command RPC. Legacy or offline owners return typed errors.
 875: func (m *Manager) ProxyWorkspaceCommand(ctx context.Context, cmd state.WorkspaceCommand) error {
 876: 	owner, peerID, err := m.WorkspaceAuthority(cmd.Layout)
 877: 	if err != nil {
 878: 		return err
 879: 	}
 880: 	if owner == state.OwnerID(m.localID) {
 881: 		cat := m.localMgr.V2Catalog()
 882: 		if cat == nil {
 883: 			return fmt.Errorf("v2 catalog not enabled")
 884: 		}
 885: 		return cat.ApplyWorkspaceCommand(cmd)
 886: 	}
 887: 	pc := m.GetPeerConnection(peerID)
 888: 	if pc == nil {
 889: 		return state.StateError{Code: state.ErrWorkspaceOwnerOffline, Field: "owner", Detail: fmt.Sprintf("workspace owner %q is offline", owner)}
 890: 	}
 891: 	if !pc.HasV2() {
 892: 		return state.StateError{Code: state.ErrLegacyPeerUnsupported, Field: "peer_id", Detail: fmt.Sprintf("peer %q does not support v2 workspace commands", peerID)}
 893: 	}
 894: 	return m.SendWorkspaceCommand(ctx, peerID, cmd)
 895: }
 896: 
 897: // RequestRemoteCreate routes a remote create to the workspace owner. The local
 898: // owner path runs directly in the coordinator; remote owners are reached over
 899: // the v2 remote-create RPC.
 900: func (m *Manager) RequestRemoteCreate(ctx context.Context, owner state.OwnerID, req state.RemoteCreateRequest) (state.RemoteCreateResult, error) {
 901: 	if owner == "" || owner == state.OwnerID(m.localID) {
 902: 		if m.v2RemoteCreate == nil {
 903: 			return state.RemoteCreateResult{}, fmt.Errorf("remote create coordinator not available")
 904: 		}
 905: 		return m.v2RemoteCreate.ExecuteRemoteCreate(ctx, req)
 906: 	}
 907: 	peerID := m.peerIDForOwner(owner)
 908: 	if peerID == "" {
 909: 		return state.RemoteCreateResult{}, state.StateError{Code: state.ErrWorkspaceOwnerOffline, Field: "owner", Detail: fmt.Sprintf("workspace owner %q is offline", owner)}
 910: 	}
 911: 	pc := m.GetPeerConnection(peerID)
 912: 	if pc == nil {
 913: 		return state.RemoteCreateResult{}, state.StateError{Code: state.ErrWorkspaceOwnerOffline, Field: "owner", Detail: fmt.Sprintf("workspace owner %q is offline", owner)}
 914: 	}
 915: 	if !pc.HasV2() {
 916: 		return state.RemoteCreateResult{}, state.StateError{Code: state.ErrLegacyPeerUnsupported, Field: "peer_id", Detail: fmt.Sprintf("peer %q does not support v2 remote creates", peerID)}
 917: 	}
 918: 	return m.SendRemoteCreate(ctx, peerID, req)
 919: }
 920: 
 921: func (m *Manager) peerIDForOwner(owner state.OwnerID) string {
 922: 	m.catalogMu.RLock()
 923: 	defer m.catalogMu.RUnlock()
 924: 	if c, ok := m.remoteCatalogs[owner]; ok {
 925: 		return c.PeerID
 926: 	}
 927: 	return ""
 928: }
 929: 
 930: // LoadRemoteCatalogCache loads persisted remote catalogs into memory. It is
 931: // idempotent and ignores missing sidecar files.
 932: func (m *Manager) LoadRemoteCatalogCache() error {
 933: 	if m.remoteStore == nil {
 934: 		return nil
 935: 	}
 936: 	catalogs, err := m.remoteStore.LoadRemoteCatalogs()
 937: 	if err != nil {
 938: 		return err
 939: 	}
 940: 	m.catalogMu.Lock()
 941: 	defer m.catalogMu.Unlock()
 942: 	for _, c := range catalogs {
 943: 		m.remoteCatalogs[c.Owner] = remoteCatalogCache{
 944: 			Owner:      c.Owner,
 945: 			Snapshot:   c,
 946: 			ReceivedAt: time.Now(),
 947: 			CatalogRev: c.Revision,
 948: 		}
 949: 	}
 950: 	return nil
 951: }
 952: 
 953: func (m *Manager) persistRemoteCatalogs() {
 954: 	m.catalogMu.RLock()
 955: 	store := m.remoteStore
 956: 	if store == nil {
 957: 		m.catalogMu.RUnlock()
 958: 		return
 959: 	}
 960: 	catalogs := make([]state.OwnerCatalogSnapshot, 0, len(m.remoteCatalogs))
 961: 	for _, c := range m.remoteCatalogs {
 962: 		catalogs = append(catalogs, cloneOwnerCatalogSnapshot(c.Snapshot))
 963: 	}
 964: 	m.catalogMu.RUnlock()
 965: 
 966: 	sort.Slice(catalogs, func(i, j int) bool { return catalogs[i].Owner < catalogs[j].Owner })
 967: 	if err := store.SaveRemoteCatalogs(catalogs); err != nil {
 968: 		logrus.WithError(err).Warn("failed to persist remote catalog caches")
 969: 	}
 970: }
 971: 
 972: func (m *Manager) forgetRemoteCatalogsForPeer(peerID string) {
 973: 	m.catalogMu.Lock()
 974: 	for owner, c := range m.remoteCatalogs {
 975: 		if c.PeerID == peerID {
 976: 			delete(m.remoteCatalogs, owner)
 977: 		}
 978: 	}
 979: 	// Clear the ownership binding so a subsequently re-added peer starts
 980: 	// clean instead of being latched to a stale owner.
 981: 	if owner, ok := m.peerOwner[peerID]; ok {
 982: 		delete(m.ownerPeer, owner)
 983: 		delete(m.peerOwner, peerID)
 984: 	}
 985: 	m.catalogMu.Unlock()
 986: 	// Persist the removal so a forgotten peer does not reappear after a
 987: 	// restart (the sidecar is written from the in-memory map).
 988: 	m.persistRemoteCatalogs()
 989: }
