1149: // pruneOffline marks long-offline peers as offline. It deliberately does not
1150: // delete v2 remote catalog caches; those are retained through reconnects and
1151: // only dropped on explicit forget.
1152: func (m *Manager) pruneOffline() {
1153: 	m.mu.Lock()
1154: 	defer m.mu.Unlock()
1155: 
1156: 	now := time.Now()
1157: 	for id, h := range m.hosts {
1158: 		if id == m.localID {
1159: 			continue
1160: 		}
1161: 		if !h.Connected && now.Sub(h.LastSeen) > OfflineTimeout {
1162: 			// Keep the host entry so its cached catalog remains addressable by
1163: 			// peer ID; only mark it as stale.
1164: 			h.Connected = false
1165: 			logrus.WithFields(logrus.Fields{
1166: 				"peer": h.Name,
1167: 				"id":   id,
1168: 			}).Debug("peer offline timeout reached; catalog retained")
1169: 		}
1170: 	}
