  8: import { useRef, useCallback, useState, useEffect } from 'react'
  9: import { Terminal } from '@xterm/xterm'
 10: import { usePreferences } from './usePreferences'
 11: import { terminalPool, normalizeSelection } from '../lib/terminalPool'
 12: import type { LeaseToken, CheckoutCallbacks, PoolIdentity, TerminalPrefs, ConnectionSnapshot } from '../lib/terminalPool'
