 17: export function useTerminal(sessionName: string, hostId?: string, backend?: string, sessionId?: string, ownerId?: string, generation?: string) {
 18:   const { prefs } = usePreferences()
 19: 
 20:   // Pool key
 21:   const poolKey = hostId ? `${hostId}/${sessionName}` : sessionName
 22: 
 23:   // Refs
 24:   const termRef = useRef<Terminal | null>(null)
 25:   const leaseRef = useRef<LeaseToken | null>(null)
 26:   const containerRef = useRef<HTMLElement | null>(null)
 27: 
 28:   // State
 29:   const [termConnected, setTermConnected] = useState<boolean>(() => {
 30:     // Synchronous initial snapshot — avoid disconnected overlay on warm switch
 31:     const snap = terminalPool.getSnapshot(poolKey)
 32:     return snap?.connected ?? false
 33:   })
 34:   const [ctrlModifierActive, setCtrlModifierActive] = useState(() => {
 35:     const snap = terminalPool.getSnapshot(poolKey)
 36:     return snap?.ctrlModifierActive ?? false
 37:   })
 38:   const [altModifierActive, setAltModifierActive] = useState(() => {
 39:     const snap = terminalPool.getSnapshot(poolKey)
 40:     return snap?.altModifierActive ?? false
 41:   })
 42:   const [selectionMenu, setSelectionMenu] = useState<{ x: number; y: number; text: string } | null>(null)
 43: 
 44:   // Callbacks — stable refs so we don't re-subscribe on every render
 45:   const callbacksRef = useRef<CheckoutCallbacks>({
 46:     onConnectionChange: (connected: boolean) => setTermConnected(connected),
 47:     onCtrlModifierChange: (active: boolean) => setCtrlModifierActive(active),
 48:     onAltModifierChange: (active: boolean) => setAltModifierActive(active),
 49:     onSelectionMenu: (menu: { x: number; y: number; text: string } | null) => setSelectionMenu(menu),
 50:   })
 51: 
 52:   // Build terminal prefs
 53:   const buildPrefs = useCallback((): TerminalPrefs => ({
 54:     theme: prefs.theme,
 55:     fontFamily: prefs.terminal.font_family,
 56:     fontSize: prefs.terminal.font_size,
 57:     scrollback: prefs.terminal.scrollback,
 58:     renderer: prefs.terminal.renderer,
 59:     unicodeGraphemes: prefs.terminal.unicode_graphemes,
 60:     predictiveEcho: prefs.terminal.predictive_echo,
 61:   }), [prefs.theme, prefs.terminal.font_family, prefs.terminal.font_size, prefs.terminal.scrollback, prefs.terminal.renderer, prefs.terminal.unicode_graphemes, prefs.terminal.predictive_echo])
 62: 
 63:   // Checkout into a container — called from Terminal.tsx layout effect
 64:   const checkout = useCallback((container: HTMLElement) => {
 65:     containerRef.current = container
 66:     const identity: PoolIdentity = { sessionName, hostId, backend, sessionId, ownerId, generation }
 67:     const lease = terminalPool.checkout(identity, buildPrefs(), container, callbacksRef.current)
 68:     leaseRef.current = lease
 69: 
 70:     // Update termRef
 71:     const snap = terminalPool.getSnapshot(lease.key)
 72:     if (snap) {
 73:       termRef.current = terminalPool.getTerminalForPaste(lease)
 74:     }
 75:   }, [sessionName, hostId, backend, sessionId, ownerId, generation, buildPrefs])
 76: 
 77:   // Checkin — called from cleanup
 78:   const checkin = useCallback(() => {
 79:     const lease = leaseRef.current
 80:     if (lease) {
 81:       terminalPool.checkin(lease)
 82:       leaseRef.current = null
 83:     }
 84:     // Connection state: keep whatever the pool currently has for the key
 85:     // (checkin does not set false). But if we're switching keys, don't
 86:     // show stale "connected" from previous key.
 87:     // The Terminal.tsx sessionName dep in the layout effect handles key switching.
 88:   }, [])
 89: 
 90:   // Disconnect — now just checkin (no disposal)
 91:   const disconnect = useCallback(() => {
 92:     checkin()
 93:   }, [checkin])
 94: 
 95:   // Connect — checkout into existing container
 96:   const connect = useCallback((container: HTMLElement) => {
 97:     checkout(container)
 98:   }, [checkout])
 99: 
100:   // Fit (lease-gated)
101:   const fit = useCallback(() => {
102:     const lease = leaseRef.current
103:     if (lease) terminalPool.fit(lease)
104:   }, [])
105: 
106:   // Focus (lease-gated)
107:   const focus = useCallback(() => {
108:     const lease = leaseRef.current
109:     if (lease) {
110:       terminalPool.focus(lease)
111:     }
112:   }, [])
113: 
114:   // Rebind / rehost (lease-gated, forced)
115:   const rebind = useCallback(() => {
116:     const lease = leaseRef.current
117:     if (lease && containerRef.current) {
118:       terminalPool.rehost(lease, containerRef.current, true)
119:       terminalPool.fit(lease)
120:     }
121:   }, [])
122: 
123:   // Send operations (lease-gated)
124:   const sendRawBytes = useCallback((bytes: Uint8Array) => {
125:     const lease = leaseRef.current
126:     if (lease) terminalPool.sendRawBytes(lease, bytes)
127:   }, [])
128: 
129:   const sendText = useCallback((text: string) => {
130:     if (!text) return
131:     sendRawBytes(new TextEncoder().encode(text))
132:   }, [sendRawBytes])
133: 
134:   const sendImage = useCallback((file: File, fallbackType: string) => {
135:     const lease = leaseRef.current
136:     if (lease) terminalPool.sendImage(lease, file, fallbackType)
137:   }, [])
138: 
139:   // Modifier toggles (lease-gated)
140:   const toggleCtrlModifier = useCallback(() => {
141:     const lease = leaseRef.current
142:     if (lease) terminalPool.toggleCtrlModifier(lease)
143:   }, [])
144: 
145:   const clearCtrlModifier = useCallback(() => {
146:     const lease = leaseRef.current
147:     if (lease) terminalPool.clearCtrlModifier(lease)
148:   }, [])
149: 
150:   const toggleAltModifier = useCallback(() => {
151:     const lease = leaseRef.current
152:     if (lease) terminalPool.toggleAltModifier(lease)
153:   }, [])
154: 
155:   const clearAltModifier = useCallback(() => {
156:     const lease = leaseRef.current
157:     if (lease) terminalPool.clearAltModifier(lease)
158:   }, [])
159: 
160:   // Selection menu (lease-gated)
161:   const setSelectionMenuFn = useCallback((menu: { x: number; y: number; text: string } | null) => {
162:     const lease = leaseRef.current
163:     if (lease) terminalPool.setSelectionMenu(lease, menu)
164:   }, [])
165: 
166:   // Preference reconfigure
167:   const reconfigure = useCallback((_renderer: string, _graphemes: boolean, _predictiveEcho: boolean) => {
168:     // Global pref reconciliation — idempotent, iterates all entries
169:     terminalPool.applyGlobalPrefs(buildPrefs())
170:   }, [buildPrefs])
171: 
172:   // On key change: checkin old, update snapshot for new key
173:   const prevKeyRef = useRef(poolKey)
174:   // Must run synchronously before any paint to avoid flash
175:   // This reads pool snapshot BEFORE the layout effect checkout runs
176:   if (prevKeyRef.current !== poolKey) {
177:     // Sync-initialize connection state from pool for the new key
178:     const snap = terminalPool.getSnapshot(poolKey)
179:     if (snap) {
180:       // These are set synchronously during render — React batches them
181:       // We use useState's initializer to set the state, but for the key
182:       // switch case we need to force update. Since we're in a render function,
183:       // we can't call setters here. Instead, we use a ref to track the
184:       // key change and let useEffect handle it.
185:     }
186:     prevKeyRef.current = poolKey
187:   }
188: 
189:   // Effect: when poolKey changes, update state from pool snapshot
190:   // This runs after the layout effect checkout and avoids the stale state problem
191:   useEffect(() => {
192:     const snap = terminalPool.getSnapshot(poolKey)
193:     if (snap) {
194:       setTermConnected(snap.connected)
195:       setCtrlModifierActive(snap.ctrlModifierActive)
196:       setAltModifierActive(snap.altModifierActive)
197:     } else {
198:       // New key with no entry yet — these will be set by checkout callbacks
199:       // But we can set to defaults
200:       setTermConnected(false)
201:       setCtrlModifierActive(false)
202:       setAltModifierActive(false)
203:     }
204:   }, [poolKey])
205: 
206:   // Cleanup on unmount — checkin if we still own a lease
207:   useEffect(() => {
208:     return () => {
209:       const lease = leaseRef.current
210:       if (lease) {
211:         terminalPool.checkin(lease)
212:         leaseRef.current = null
213:       }
214:     }
215:   }, [])
216: 
217:   return {
218:     termRef,
219:     connect,
220:     disconnect,
221:     fit,
222:     rebind,
223:     focus,
224:     termConnected,
225:     sendRawBytes,
226:     sendText,
227:     sendImage,
228:     ctrlModifierActive,
229:     toggleCtrlModifier,
230:     clearCtrlModifier,
231:     altModifierActive,
232:     toggleAltModifier,
233:     clearAltModifier,
234:     selectionMenu,
235:     setSelectionMenu: setSelectionMenuFn,
236:     reconfigure,
237:   }
