763: // runShellNameWatcher polls active-pane foreground commands and triggers AI
764: // naming for meaningful new processes.
765: func runShellNameWatcher(ctx context.Context, mgr *state.Manager, adapter *daemonAdapter, provider ForegroundProvider) {
766: 	ticker := time.NewTicker(5 * time.Second)
767: 	defer ticker.Stop()
768: 
769: 	lastCmd := make(map[string]string)
770: 	lastFire := make(map[string]time.Time)
771: 	named := make(map[string]bool)
772: 	const firstInterval = 20 * time.Second
773: 	const renameInterval = 3 * time.Minute
774: 
775: 	for {
776: 		select {
777: 		case <-ctx.Done():
778: 			return
779: 		case <-ticker.C:
780: 			for _, d := range adapter.List() {
781: 				pid := d.ShellPid
782: 				if pid == 0 {
783: 					pid = d.Pid
784: 				}
785: 				cmd, ok := provider.Foreground(pid)
786: 				if !ok {
787: 					continue
788: 				}
789: 				cmd = strings.TrimSpace(cmd)
790: 				if cmd == "" || shellNames[cmd] || trivialCmds[cmd] || cmd == lastCmd[d.ID] {
791: 					continue
792: 				}
793: 				lastCmd[d.ID] = cmd
794: 
795: 				interval := firstInterval
796: 				if named[d.ID] {
797: 					interval = renameInterval
798: 				}
799: 				if t, ok := lastFire[d.ID]; ok && time.Since(t) < interval {
800: 					continue
801: 				}
802: 				lastFire[d.ID] = time.Now()
803: 				named[d.ID] = true
804: 
805: 				cmds := []string{cmd}
806: 				if content, err := adapter.Capture(d.ID); err == nil {
807: 					cmds = recentCommands(content, cmd)
808: 				}
809: 				go mgr.TriggerShellNaming(d.ID, cmds)
810: 			}
811: 		}
812: 	}
813: }
814: 
815: // recentCommands extracts up to a handful of recent input lines from captured
816: // pane content as a hint for naming.
817: func recentCommands(content, foreground string) []string {
818: 	lines := strings.Split(content, "\n")
819: 	var out []string
820: 	for i := len(lines) - 1; i >= 0 && len(out) < 6; i-- {
821: 		l := strings.TrimSpace(lines[i])
822: 		if l == "" {
823: 			continue
824: 		}
825: 		l = strings.TrimLeft(l, "$#%> ")
826: 		if l == "" {
827: 			continue
828: 		}
829: 		out = append(out, l)
830: 	}
831: 	if len(out) == 0 {
832: 		return []string{foreground}
833: 	}
834: 	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
835: 		out[i], out[j] = out[j], out[i]
836: 	}
837: 	return out
838: }
