848: // v2RuntimeEnricher supplies live runtime fields for v2 catalog records
849: // without mutating persisted state.
850: type v2RuntimeEnricher struct {
851: 	adapter    *daemonAdapter
852: 	actTracker *activity.Tracker
853: 
854: 	previewMu    sync.Mutex
855: 	previewCache map[string]*v2PreviewCacheEntry
856: }
857: 
858: // v2PreviewCacheEntry holds a throttled prompt-preview snapshot for a single
859: // session so the (up to) 64KiB PTY capture only runs periodically instead of
860: // on every catalog enrichment call. This mirrors the throttle pattern used by
861: // state.Manager's legacy preview cache (see pkg/state/preview.go).
862: type v2PreviewCacheEntry struct {
863: 	preview     string
864: 	lastAttempt time.Time
865: 	inFlight    bool
866: }
867: 
868: // v2PromptPreviewInterval throttles prompt-preview PTY captures during v2
869: // catalog enrichment. Matches the legacy manager's promptPreviewInterval.
870: const v2PromptPreviewInterval = 30 * time.Second
871: 
872: // previewFor returns the cached prompt preview for a session immediately,
873: // without blocking the catalog projection path. When the cached preview is
874: // stale (older than v2PromptPreviewInterval) and no refresh is already in
875: // flight for this session, it kicks off exactly one asynchronous PTY capture
876: // to refresh the cache for subsequent calls. This keeps catalog snapshot
877: // publication off the PTY I/O path entirely.
878: func (e *v2RuntimeEnricher) previewFor(sessionID string) string {
879: 	e.previewMu.Lock()
880: 	if e.previewCache == nil {
881: 		e.previewCache = make(map[string]*v2PreviewCacheEntry)
882: 	}
883: 	entry := e.previewCache[sessionID]
884: 	if entry == nil {
885: 		entry = &v2PreviewCacheEntry{}
886: 		e.previewCache[sessionID] = entry
887: 	}
888: 	cached := entry.preview
889: 	due := time.Since(entry.lastAttempt) >= v2PromptPreviewInterval
890: 	shouldRefresh := due && !entry.inFlight
891: 	if shouldRefresh {
892: 		entry.inFlight = true
893: 		entry.lastAttempt = time.Now()
894: 	}
895: 	e.previewMu.Unlock()
896: 
897: 	if shouldRefresh {
898: 		go e.refreshPreview(sessionID)
899: 	}
900: 
901: 	return cached
902: }
903: 
904: // refreshPreview performs the actual (potentially slow) PTY capture off the
905: // synchronous enrichment path and stores the result for the next previewFor
906: // call to observe.
907: func (e *v2RuntimeEnricher) refreshPreview(sessionID string) {
908: 	defer func() {
909: 		e.previewMu.Lock()
910: 		if entry := e.previewCache[sessionID]; entry != nil {
911: 			entry.inFlight = false
912: 		}
913: 		e.previewMu.Unlock()
914: 	}()
915: 
916: 	content, err := e.adapter.CaptureTail(sessionID, 64*1024)
917: 	if err != nil {
918: 		return
919: 	}
920: 	preview := model.ExtractPromptPreview(content)
921: 
922: 	e.previewMu.Lock()
923: 	if entry := e.previewCache[sessionID]; entry != nil {
924: 		entry.preview = preview
925: 	}
926: 	e.previewMu.Unlock()
927: }
928: 
929: func (e *v2RuntimeEnricher) Enrich(ref state.SessionRef, rec state.LocalSessionRecord) state.SessionRuntime {
930: 	var rt state.SessionRuntime
931: 	for _, d := range e.adapter.List() {
932: 		if d.ID != string(ref.Session) {
933: 			continue
934: 		}
935: 		rt.DaemonPID = d.Pid
936: 		rt.ShellPID = d.ShellPid
937: 		rt.CurrentCommand = d.Shell
938: 		rt.CurrentPath = d.Cwd
939: 
940: 		pid := d.ShellPid
941: 		if pid == 0 {
942: 			pid = d.Pid
943: 		}
944: 		if pid > 0 {
945: 			if liveCwd, err := os.Readlink(fmt.Sprintf("/proc/%d/cwd", pid)); err == nil && liveCwd != "" {
946: 				rt.CurrentPath = liveCwd
947: 			}
948: 		}
949: 		rt.PromptPreview = e.previewFor(d.ID)
950: 		if e.actTracker != nil {
951: 			if snap := e.actTracker.Get(d.ID); snap != nil && snap.IdleSeconds >= 0 {
952: 				rt.LastActivity = snap.LastActive
953: 			}
954: 		}
955: 		break
956: 	}
957: 	return rt
958: }   1: //
