  37: // ── Fake HTMLElement ──────────────────────────────────────────────────
  38: 
  39: interface FakeEl extends HTMLElement {
  40:   _fire(type: string, ...args: any[]): void
  41:   _children: HTMLElement[]
  42:   _parent: HTMLElement | null
  43:   _listeners: Map<string, Array<(...args: any[]) => void>>
  44: }
  45: 
  46: function fakeEl(tag = 'div'): FakeEl {
  47:   const children: HTMLElement[] = []
  48:   let parent: HTMLElement | null = null
  49:   const listeners = new Map<string, Array<(...args: any[]) => void>>()
  50:   const styleObj: Record<string, string> = {}
  51: 
  52:   const el = {
  53:     tagName: tag.toUpperCase(),
  54:     _children: children,
  55:     _parent: parent,
  56: 
  57:     get ownerDocument() {
  58:       return {
  59:         body: {
  60:           appendChild(child: HTMLElement) {
  61:             (child as FakeEl)._parent = el as any
  62:             return child
  63:           },
  64:         } as any,
  65:         defaultView: null,
  66:       } as unknown as Document
  67:     },
  68: 
  69:     appendChild(child: HTMLElement) {
  70:       if ((child as FakeEl)._parent) {
  71:         (child as FakeEl)._parent?.removeChild(child)
  72:       }
  73:       children.push(child)
  74:       ;(child as FakeEl)._parent = el
  75:       return child
  76:     },
  77:     removeChild(child: HTMLElement) {
  78:       const idx = children.indexOf(child)
  79:       if (idx > -1) { children.splice(idx, 1); (child as FakeEl)._parent = null }
  80:       return child
  81:     },
  82:     remove() {
  83:       if (parent) { parent.removeChild(el); parent = null }
  84:     },
  85:     get parentElement() { return parent },
  86:     get children() { return children as unknown as HTMLCollection },
  87: 
  88:     style: {
  89:       setProperty(k: string, v: string) { styleObj[k] = v },
  90:       getPropertyValue(k: string) { return styleObj[k] || '' },
  91:       position: '', top: '', left: '', width: '', height: '',
  92:       overflow: '', pointerEvents: '', visibility: '', opacity: '',
  93:     } as unknown as CSSStyleDeclaration,
  94: 
  95:     clientWidth: 800,
  96:     clientHeight: 600,
  97:     scrollTop: 0,
  98: 
  99:     querySelector(_sel: string): HTMLElement | null { return null },
 100:     getElementsByClassName(): HTMLCollectionOf<Element> { return { length: 0, item: () => null, namedItem: () => null } as any },
 101:     querySelectorAll(): NodeListOf<Element> { return { length: 0, item: () => null, forEach: () => {} } as any },
 102: 
 103:     addEventListener(type: string, fn: any, _opts?: any) {
 104:       if (!listeners.has(type)) listeners.set(type, [])
 105:       listeners.get(type)!.push(fn)
 106:     },
 107:     removeEventListener(type: string, fn: any) {
 108:       const arr = listeners.get(type)
 109:       if (arr) { const idx = arr.indexOf(fn); if (idx > -1) arr.splice(idx, 1) }
 110:     },
 111:     dispatchEvent(event: any) {
 112:       const arr = listeners.get(event.type as string)
 113:       arr?.forEach(fn => fn(event))
 114:       return true
 115:     },
 116:     _fire(type: string, ...args: any[]) {
 117:       const arr = listeners.get(type)
 118:       arr?.forEach(fn => fn(...args))
 119:     },
 120:     _listeners: listeners,
 121:   } as unknown as FakeEl
 122: 
 123:   return el
 124: }
 125: 
 126: // ── Fake Terminal ─────────────────────────────────────────────────────
 127: 
 128: class FakeTerminal {
 129:   options: any
 130:   element: HTMLElement
 131:   cols = 80
 132:   rows = 24
 133:   buffer = {
 134:     active: {
 135:       type: 'normal' as const,
 136:       cursorX: 0, cursorY: 0,
 137:       baseY: 100, viewportY: 95, length: 100,
 138:       getLine: (_i: number) => null,
 139:     },
 140:   }
 141:   private _dataListeners: Array<(data: string) => void> = []
 142:   private _resizeListeners: Array<(info: { cols: number; rows: number }) => void> = []
 143: 
 144:   constructor(options: any) {
 145:     terminalCreateCount++
 146:     this.options = options
 147:     this.element = fakeEl()
 148:   }
 149: 
 150:   loadAddon(_addon: any) { addonCreateCount++ }
 151:   open(_container: HTMLElement) {}
 152:   dispose() { terminalDisposeCount++ }
 153:   onData(fn: (data: string) => void) {
 154:     this._dataListeners.push(fn)
 155:     return { dispose: () => {
 156:       const idx = this._dataListeners.indexOf(fn)
 157:       if (idx > -1) this._dataListeners.splice(idx, 1)
 158:     }}
 159:   }
 160:   onResize(fn: (info: { cols: number; rows: number }) => void) {
 161:     this._resizeListeners.push(fn)
 162:     return { dispose: () => {
 163:       const idx = this._resizeListeners.indexOf(fn)
 164:       if (idx > -1) this._resizeListeners.splice(idx, 1)
 165:     }}
 166:   }
 167:   onSelectionChange(_fn: () => void) { return { dispose: () => {} } }
 168:   attachCustomKeyEventHandler(_fn: (e: any) => boolean) {}
 169:   getSelection() { return '' }
 170:   clearSelection() {}
 171:   scrollToBottom() {}
 172:   scrollLines(_delta: number) {}
 173:   focus() {}
 174:   refresh(_start: number, _end: number) {}
 175:   writes: { data: Uint8Array | string; cb?: () => void }[] = []
 176:   write(data: any, cb?: () => void) {
 177:     if (data instanceof ArrayBuffer) {
 178:       this.writes.push({ data: new Uint8Array(data), cb })
 179:     } else if (typeof data === 'object' && data && typeof data.length === 'number' && !(data instanceof Uint8Array)) {
 180:       this.writes.push({ data: new Uint8Array(data), cb })
 181:     } else {
 182:       this.writes.push({ data, cb })
 183:     }
 184:     if (cb) cb()
 185:   }
 186: 
 187:   _fireData(data: string) { this._dataListeners.forEach(fn => fn(data)) }
 188:   _fireResize(cols: number, rows: number) {
 189:     this.cols = cols; this.rows = rows
 190:     this._resizeListeners.forEach(fn => fn({ cols, rows }))
 191:   }
 192: }
