1042:   it('partial marker prefix straddle is reassembled without leaking tail', () => {
1043:     const { ws, term } = openSession('s1')
1044:     vi.useFakeTimers()
1045:     vi.advanceTimersByTime(250)
1046:     const markerPrefix = new Uint8Array([0x1b, 0x5b, 0x3f, 0x32, 0x30, 0x32])
1047:     for (let partialLen = 1; partialLen <= markerPrefix.length; partialLen++) {
1048:       const chunk1 = concatU8([new Uint8Array([0x4c, 0x4f, 0x47, 0x49, 0x4e]), markerPrefix.subarray(0, partialLen)])
1049:       const chunk2 = concatU8([markerPrefix.subarray(partialLen), new Uint8Array([0x36, 0x68, 0x57, 0x4f, 0x52, 0x4c, 0x44])])
1050:       const esu = new Uint8Array([0x1b, 0x5b, 0x3f, 0x32, 0x30, 0x32, 0x36, 0x6c])
1051:       term.writes = []
1052:       ws._message(chunk1.buffer)
1053:       ws._message(concatU8([chunk2, esu]).buffer)
1054:       vi.advanceTimersByTime(0)
1055:       const bytes = term.writes.filter(w => w.data instanceof Uint8Array).flatMap(w => [...(w.data as Uint8Array)])
1056:       expect(bytes).toEqual([0x4c, 0x4f, 0x47, 0x49, 0x4e, 0x57, 0x4f, 0x52, 0x4c, 0x44])
1057:       for (const w of term.writes) {
1058:         const b = w.data instanceof Uint8Array ? w.data : new TextEncoder().encode(String(w.data))
1059:         for (let i = 0; i <= b.length - 3; i++) {
1060:           if (b[i] === 0x1b && b[i + 1] === 0x5b && b[i + 2] === 0x3f) {
1061:             throw new Error(`leaked marker prefix in write at offset ${i}`)
1062:           }
1063:         }
1064:       }
1065:     }
1066:     vi.useRealTimers()
1067:   })
