1231:   // ── Terminal identity preservation across rename + generation change ──
1232: 
1233:   it('terminal instance identity survives both rename and generation-change events', () => {
1234:     const container = fakeEl()
1235:     // Checkout with stable identity: immutable sessionId + generation.
1236:     const lease = pool.checkout(
1237:       defStableId('old-label', 'sid-42', 'gen-1', 'hostX'),
1238:       defPrefs(),
1239:       container,
1240:       noopCbs(),
1241:     )
1242:     const oldKey = lease.key
1243: 
1244:     // Capture terminal instance reference before any mutations.
1245:     const terminalBefore = pool.getTerminalForPaste(lease)!
1246:     expect(terminalBefore).not.toBeNull()
1247: 
1248:     // Record counters before events.
1249:     const tcB = terminalCreateCount
1250:     const tdB = terminalDisposeCount
1251:     const sockOpenB = socketOpenCount
1252: 
1253:     // Event 1: Rename (label change). Simulate by rekeying the entry.
1254:     // Rekey moves entry to new key but preserves terminal instance.
1255:     const newKey = 'hostX/new-label'
1256:     pool.rekey(oldKey, newKey)
1257: 
1258:     // Assert: terminal NOT disposed, NOT recreated.
1259:     expect(terminalCreateCount).toBe(tcB) // no new terminal created
1260:     expect(terminalDisposeCount).toBe(tdB) // old terminal NOT disposed
1261: 
1262:     // Assert: pool entry moved to new key, terminal still same.
1263:     expect(hasEntry(pool, oldKey)).toBe(false)
1264:     expect(hasEntry(pool, newKey)).toBe(true)
1265:     const terminalAfterRename = getEntry(pool, newKey).terminal
1266:     expect(terminalAfterRename).toBe(terminalBefore)
1267: 
1268:     // Event 2: Generation change (daemon recovery). Simulate by updateGeneration.
1269:     // updateGeneration reconnects the SAME pool entry in place (new socket, same terminal).
1270:     const genBefore = socketOpenCount
1271:     pool.updateGeneration(newKey, 'gen-2')
1272: 
1273:     // Assert: terminal still NOT disposed, NOT recreated.
1274:     expect(terminalCreateCount).toBe(tcB) // no new terminal
1275:     expect(terminalDisposeCount).toBe(tdB) // original terminal still NOT disposed
1276:     // Assert: new socket connection opened (reconnect happened).
1277:     expect(socketOpenCount).toBeGreaterThan(genBefore)
1278: 
1279:     // Assert: terminal instance identity unchanged after both events.
1280:     const terminalAfterGenChange = getEntry(pool, newKey).terminal
1281:     expect(terminalAfterGenChange).toBe(terminalBefore) // same instance throughout
1282:     expect(terminalAfterGenChange).toBe(terminalAfterRename) // transitive
1283: 
1284:     // Assert: pool entry mutation fields updated correctly (identity only).
1285:     const finalEntry = getEntry(pool, newKey)
1286:     expect(finalEntry.identity.sessionId).toBe('sid-42')
1287:     expect(finalEntry.identity.generation).toBe('gen-2') // generation changed
1288:   })
