   2: // terminalPool.ts — Frontend-owned terminal instance pool (facade).
   3: //
   4: // Checkout/checkin lease behavior is still owned here, but connection
   5: // lifecycle, replay assembly, and unavoidable xterm internals are delegated
   6: // to focused modules:
   7: //   - connectionMachine.ts: WebSocket state machine and timers
   8: //   - replayBuffer.ts: bounded replay byte assembly
   9: //   - xtermCompat.ts: the only _core access boundary
  10: //
  11: 
  12: import { Terminal } from '@xterm/xterm'
  13: import { FitAddon } from '@xterm/addon-fit'
  14: import { WebLinksAddon } from '@xterm/addon-web-links'
  15: import { ClipboardAddon, type IClipboardProvider, type ClipboardSelectionType } from '@xterm/addon-clipboard'
  16: import { WebglAddon } from '@xterm/addon-webgl'
  17: import { ImageAddon } from '@xterm/addon-image'
  18: import { UnicodeGraphemesAddon } from '@xterm/addon-unicode-graphemes'
  19: import { PredictiveEcho } from './predictive-echo'
  20: import { getXtermTheme } from '../theme'
  21: import { ConnectionMachine } from './terminal/connectionMachine'
  22: import { ReplayBuffer } from './terminal/replayBuffer'
  23: import { neutralizeXtermScrollbarFallback, measureXtermCharSize } from './terminal/xtermCompat'
  24: import { transferNode } from './pip'
  25: 
  26: // Re-export the public contracts owned by the submodules so existing callers
  27: // keep working without importing through the submodule path.
  28: export { MAX_REPLAY_BUFFER_BYTES, concatU8 } from './terminal/replayBuffer'
  29: 
  30: // Allow tests to inject a different transfer primitive.
  31: let _transferNode: ((node: HTMLElement, dest: HTMLElement) => { crossedDocument: boolean }) | null = transferNode
  32: export function __injectTransferNode(
  33:   fn: (node: HTMLElement, dest: HTMLElement) => { crossedDocument: boolean },
  34: ) {
  35:   _transferNode = fn
  36: }
