  38: // --- internal helpers --------------------------------------------------
  39: 
  40: // Clipboard helpers
  41: let pendingClipboard: string | null = null
  42: 
  43: function execCommandCopy(text: string): boolean {
  44:   const ta = document.createElement('textarea')
  45:   ta.value = text
  46:   ta.style.position = 'fixed'
  47:   ta.style.left = '-9999px'
  48:   ta.style.opacity = '0'
  49:   document.body.appendChild(ta)
  50:   ta.select()
  51:   let ok = false
  52:   try {
  53:     ok = document.execCommand('copy')
  54:   } catch { /* ignored */ }
  55:   document.body.removeChild(ta)
  56:   return ok
  57: }
  58: 
  59: export function normalizeSelection(text: string): string {
  60:   return text.replace(/[ \t]+$/gm, '')
  61: }
  62: 
  63: function copyToClipboard(text: string): Promise<void> {
  64:   text = normalizeSelection(text)
  65:   if (navigator.clipboard) {
  66:     return navigator.clipboard.writeText(text).catch(() => {
  67:       if (!execCommandCopy(text)) {
  68:         pendingClipboard = text
  69:       }
  70:     })
  71:   }
  72:   if (!execCommandCopy(text)) {
  73:     pendingClipboard = text
  74:   }
  75:   return Promise.resolve()
  76: }
  77: 
  78: function flushPendingClipboard(): void {
  79:   if (pendingClipboard !== null) {
  80:     const text = pendingClipboard
  81:     pendingClipboard = null
  82:     if (navigator.clipboard) {
  83:       navigator.clipboard.writeText(text).catch(() => {
  84:         if (!execCommandCopy(text)) {
  85:           pendingClipboard = text
  86:         }
  87:       })
  88:     } else if (!execCommandCopy(text)) {
  89:       pendingClipboard = text
  90:     }
  91:   }
  92: }
  93: 
  94: function requestClipboardPermission(): void {
  95:   navigator.permissions?.query({ name: 'clipboard-write' as PermissionName }).catch(() => {})
  96: }
  97: 
  98: const clipboardProvider: IClipboardProvider = {
  99:   readText(selection: ClipboardSelectionType): Promise<string> {
 100:     if (selection !== 'c') return Promise.resolve('')
 101:     return navigator.clipboard?.readText?.() ?? Promise.resolve('')
 102:   },
 103:   writeText(selection: ClipboardSelectionType, text: string): Promise<void> {
 104:     if (selection !== 'c') return Promise.resolve()
 105:     return copyToClipboard(text)
 106:   },
 107: }
 108: 
 109: const MAX_PASTED_FILE_BYTES = 10 * 1024 * 1024
 110: 
 111: export function concatU8Legacy(parts: Uint8Array[]): Uint8Array {
 112:   let len = 0
 113:   for (const p of parts) len += p.length
 114:   const out = new Uint8Array(len)
 115:   let off = 0
 116:   for (const p of parts) {
 117:     out.set(p, off)
 118:     off += p.length
 119:   }
 120:   return out
 121: }
 122: 
 123: function indexOfU8(haystack: Uint8Array, needle: Uint8Array, start = 0): number {
 124:   if (needle.length === 0) return start
 125:   outer: for (let i = start; i <= haystack.length - needle.length; i++) {
 126:     for (let j = 0; j < needle.length; j++) {
 127:       if (haystack[i + j] !== needle[j]) continue outer
 128:     }
 129:     return i
 130:   }
 131:   return -1
 132: }
 133: 
 134: // Shared prefix of the DEC mode 2026 synchronized-update markers.
 135: // BSU = \x1b[?2026h, ESU = \x1b[?2026l. The 6-byte prefix is shared; the
 136: // 7th byte disambiguates start (0x68) vs end (0x6c).
 137: const SYNC_MARKER_PREFIX = new Uint8Array([0x1b, 0x5b, 0x3f, 0x32, 0x30, 0x32, 0x36])
 138: 
 139: function bytesToBase64(bytes: Uint8Array): string {
 140:   let binary = ''
 141:   const chunkSize = 0x8000
 142:   for (let i = 0; i < bytes.length; i += chunkSize) {
 143:     const chunk = bytes.subarray(i, i + chunkSize)
 144:     binary += String.fromCharCode(...chunk)
 145:   }
 146:   return btoa(binary)
 147: }
 148: 
 149: async function sendPastedImage(
 150:   ws: WebSocket,
 151:   file: File,
 152:   fallbackType: string,
 153:   entry: PoolEntry,
 154:   gen: number,
 155: ): Promise<void> {
 156:   if (file.size > MAX_PASTED_FILE_BYTES) {
 157:     return
 158:   }
 159:   const buffer = await file.arrayBuffer()
 160:   // Re-validate lease after async gap — entry may have been checked in/out
 161:   if (entry.generation !== gen || entry.connection.socket !== ws || ws.readyState !== WebSocket.OPEN) return
 162:   ws.send(JSON.stringify({
 163:     type: 'paste-image',
 164:     data: bytesToBase64(new Uint8Array(buffer)),
 165:     mime: file.type || fallbackType,
 166:     filename: file.name,
 167:   }))
 168: }
 169: 
 170: // Scroll-preserving fit.
 171: //
 172: // fitAddon.fit() reflows rows and can move the viewport, so we restore the
 173: // user's prior scroll anchor afterward.
 174: //
 175: // CRITICAL: we decide whether to preserve a non-bottom offset using
 176: // entry.userScrolled (set only by real wheel/touch/scrollbar gestures), NOT
 177: // buffer geometry. xterm updates viewportY asynchronously during rapid writes
 178: // (spinner/redraw animations), so capturing `baseY - viewportY` mid-frame
 179: // reads a stale in-between state and "restores" the terminal to a phantom
 180: // offset, pinning it mid-history and flashing on every redraw.
 181: function fitPreservingScroll(
 182:   entry: PoolEntry,
 183:   container: HTMLElement,
 184:   opts?: { refreshAfter?: boolean },
 185: ): void {
 186:   const term = entry.terminal
 187:   const fitAddon = entry.fitAddon
 188:   if (container.clientWidth <= 0 || container.clientHeight <= 0) return
 189: 
 190:   const myEpoch = ++entry.fitEpoch
 191:   const buf = term.buffer.active
 192:   // Only preserve a real user offset. geometry-based distFromBottom is
 193:   // unreliable during async writes.
 194:   const userOffset = entry.userScrolled ? Math.max(0, buf.baseY - buf.viewportY) : 0
 195: 
 196:   const isStale = () => entry.fitEpoch !== myEpoch
 197: 
 198:   neutralizeXtermScrollbarFallback(term)
 199:   fitAddon.fit()
 200: 
 201:   if (opts?.refreshAfter) {
 202:     try { term.refresh(0, term.rows - 1) } catch { /* renderer dispose race */ }
 203:   }
 204: 
 205:   if (userOffset === 0) {
 206:     // Following output: pin to bottom once. xterm keeps it there on writes.
 207:     try { term.scrollToBottom() } catch { /* renderer dispose race */ }
 208:     const forceDOM = () => {
 209:       if (isStale()) return
 210:       const vp = container.querySelector('.xterm-viewport') as HTMLElement | null
 211:       if (vp && vp.scrollTop + vp.clientHeight < vp.scrollHeight - 5) {
 212:         vp.scrollTop = vp.scrollHeight
 213:       }
 214:     }
 215:     requestAnimationFrame(forceDOM)
 216:     return
 217:   }
 218: 
 219:   // User is genuinely scrolled up: restore the captured offset, but only
 220:   // across a single deferred frame (xterm recomputes viewport async).
 221:   const restoreOnce = () => {
 222:     if (isStale() || !entry.userScrolled) return
 223:     try {
 224:       const after = term.buffer.active
 225:       if (userOffset > after.baseY) { term.scrollToBottom(); return }
 226:       const target = after.baseY - userOffset
 227:       const delta = target - after.viewportY
 228:       if (delta !== 0) term.scrollLines(delta)
 229:     } catch { /* renderer dispose race */ }
 230:   }
 231:   restoreOnce()
 232:   requestAnimationFrame(restoreOnce)
 233: }
