 297: const defaultFactory: PoolFactory = {
 298:   createTerminal: (options) => new Terminal(options),
 299:   createFitAddon: () => new FitAddon(),
 300:   createWebLinksAddon: () => new WebLinksAddon(),
 301:   createClipboardAddon: (provider) => new ClipboardAddon(undefined, provider),
 302:   createWebglAddon: () => {
 303:     try { return new WebglAddon() } catch { return null }
 304:   },
 305:   createImageAddon: () => {
 306:     try {
 307:       return new ImageAddon({
 308:         pixelLimit: 4_000_000,
 309:         sixelSupport: true,
 310:         sixelSizeLimit: 8_000_000,
 311:         storageLimit: 24,
 312:         showPlaceholder: true,
 313:         iipSupport: false,
 314:       })
 315:     } catch { return null }
 316:   },
 317:   createUnicodeGraphemesAddon: () => {
 318:     try { return new UnicodeGraphemesAddon() } catch { return null }
 319:   },
 320:   createPredictiveEcho: (term) => {
 321:     try { return new PredictiveEcho(term) } catch { return null }
 322:   },
 323:   createWebSocket: (url) => new WebSocket(url),
 324: }
 325: 
 326: // --- Pool entry state --------------------------------------------------
 327: 
 328: interface PoolEntry {
 329:   // Identity
 330:   key: string
 331:   identity: PoolIdentity
 332: 
 333:   // Core resources
 334:   terminal: Terminal
 335:   fitAddon: FitAddon
 336:   webglAddon: WebglAddon | null
 337:   imageAddon: ImageAddon | null
 338:   graphemesAddon: UnicodeGraphemesAddon | null
 339:   graphemesLoaded: boolean
 340:   predictiveEcho: PredictiveEcho | null
 341:   predictiveEchoEnabled: boolean
 342: 
 343:   // Delegates
 344:   connection: ConnectionMachine
 345:   replayBuffer: ReplayBuffer
 346: 
 347:   // Connection
 348:   connected: boolean
 349: 
 350:   // Lease
 351:   generation: number
 352: 
 353:   // Fit-scheduling epoch. Incremented on every fit() and on user scroll so
 354:   // stale deferred scroll-restore callbacks from a prior fit can no-op.
 355:   fitEpoch: number
 356: 
 357:   // True only when the user has taken control of the viewport via a real
 358:   // gesture (wheel, touch, scrollbar drag). Buffer geometry is NOT a reliable
 359:   // signal: xterm updates viewportY asynchronously during rapid writes.
 360:   userScrolled: boolean
 361: 
 362:   // Active container state
 363:   activeContainer: HTMLElement | null
 364:   activeCallbacks: CheckoutCallbacks | null
 365:   listenerCleanup: (() => void) | null
 366: 
 367:   // Hidden host
 368:   hiddenHost: HTMLElement | null
 369: 
 370:   // Dimensions
 371:   lastCols: number
 372:   lastRows: number
 373:   pendingResizeOnOpen: boolean
 374: 
 375:   // Modifier state
 376:   ctrlModifierActive: boolean
 377:   altModifierActive: boolean
 378:   suppressedInput: string | null
 379: 
 380:   // Selection
 381:   selectionMenu: { x: number; y: number; text: string } | null
 382: 
 383:   // Applied preferences
 384:   appliedPrefs: TerminalPrefs | null
 385: 
 386:   // Live output sync markers
 387:   syncCarryover: Uint8Array | null
 388:   syncActive: boolean
 389:   syncBuffer: Uint8Array[]
 390: 
 391:   // Echo/write coordination
 392:   writePending: boolean
 393: }
 394: 
 395: // --- Pool singleton ----------------------------------------------------
 396: 
 397: export class TerminalPool {
 398:   private entries = new Map<string, PoolEntry>()
 399:   private factory: PoolFactory
 400:   private poolRoot: HTMLElement | null = null
 401: 
 402:   constructor(factory?: PoolFactory) {
 403:     this.factory = factory ?? defaultFactory
 404:   }
 405: 
 406:   // ── public API: key management ──────────────────────────────────────
 407: 
 408:   /** Canonical key from session identity. */
 409:   static keyFor(sessionName: string, hostId?: string): string {
 410:     return hostId ? `${hostId}/${sessionName}` : sessionName
 411:   }
 412: 
 413:   keyFor(sessionName: string, hostId?: string): string {
 414:     return TerminalPool.keyFor(sessionName, hostId)
 415:   }
 416: 
 417:   /** Synchronous snapshot lookup without side effects. */
 418:   getSnapshot(key: string): ConnectionSnapshot | null {
 419:     const entry = this.entries.get(key)
 420:     if (!entry) return null
 421:     return {
 422:       connected: entry.connected,
 423:       ctrlModifierActive: entry.ctrlModifierActive,
 424:       altModifierActive: entry.altModifierActive,
 425:     }
 426:   }
 427: 
 428:   /** Return entries count (for tests). */
 429:   get size(): number {
 430:     return this.entries.size
 431:   }
 432: 
 433:   /** All current keys (for tests). */
 434:   get keys(): IterableIterator<string> {
 435:     return this.entries.keys()
 436:   }
 437: 
 438:   // ── public API: checkout / checkin ──────────────────────────────────
 439: 
 440:   checkout(
 441:     identity: PoolIdentity,
 442:     prefs: TerminalPrefs,
 443:     container: HTMLElement,
 444:     callbacks: CheckoutCallbacks,
 445:     factory?: PoolFactory,
 446:   ): LeaseToken {
 447:     // Canonical pool identity is the immutable SessionRef (sessionId/ownerId),
 448:     // NOT the display label. A rename must never rekey, dispose, or reconnect
 449:     // an open terminal; label-only changes hit the same pool entry.
 450:     
 451:     // Guard: v2 session with missing sessionId is an invariant violation.
 452:     // If the caller provides ownerId or generation (v2 identity intent), sessionId
 453:     // MUST be present. Do not silently fall back to name-based attach.
 454:     if (identity.backend === 'daemon' && (identity.ownerId || identity.generation) && !identity.sessionId) {
 455:       const msg = `v2 session requires sessionId: ownerId=${identity.ownerId}, generation=${identity.generation}, sessionName=${identity.sessionName}`
 456:       console.error(msg)
 457:       throw new Error(msg)
 458:     }
 459:     
 460:     const canonical = identity.sessionId
 461:       ? TerminalPool.keyFor(identity.sessionId, identity.ownerId ?? identity.hostId)
 462:       : TerminalPool.keyFor(identity.sessionName, identity.hostId)
 463:     const key = canonical
 464:     const ef = factory ?? this.factory
 465:     let entry = this.entries.get(key)
 466: 
 467:     // Dispose & recreate if backend identity changed for same key.
 468:     if (entry) {
 469:       const backendChanged = entry.identity.backend !== (identity.backend ?? undefined)
 470:       if (backendChanged) {
 471:         this.disposeEntry(entry)
 472:         this.entries.delete(key)
 473:         entry = undefined
 474:       }
 475:     }
 476: 
 477:     // Cold create
 478:     if (!entry) {
 479:       entry = this.createEntry(key, identity, prefs, ef)
 480:       this.entries.set(key, entry)
 481:     }
 482: 
 483:     // Increment lease — invalidate any previous owner
 484:     entry.generation++
 485:     const lease: LeaseToken = { generation: entry.generation, key }
 486: 
 487:     // Remove old foreground listeners
 488:     if (entry.listenerCleanup) {
 489:       entry.listenerCleanup()
 490:       entry.listenerCleanup = null
 491:     }
 492:     entry.activeCallbacks = callbacks
 493: 
 494:     // Bind terminal to the foreground container.
 495:     const term = entry.terminal
 496:     const root = term.element as HTMLElement | undefined
 497:     if (root) {
 498:       // Already opened: move the existing DOM node into the new container first.
 499:       (_transferNode ?? transferNode)(root, container)
 500:     }
 501:     try { term.open(container) } catch { /* ignored */ }
 502:     neutralizeXtermScrollbarFallback(term)
 503: 
 504:     entry.activeContainer = container
 505: 
 506:     // Attach foreground listeners
 507:     this.attachListeners(entry)
 508: 
 509:     // Reconcile preferences
 510:     this.reconcilePrefs(entry, prefs)
 511: 
 512:     // Fit and resize
 513:     if (container.clientWidth > 0 && container.clientHeight > 0) {
 514:       fitPreservingScroll(entry, container, { refreshAfter: true })
 515:       if (entry.connection.connected) {
 516:         const ws = entry.connection.socket
 517:         if (ws && ws.readyState === WebSocket.OPEN) {
 518:           const { cols, rows } = entry.terminal
 519:           ws.send(JSON.stringify({ type: 'resize', cols, rows }))
 520:           entry.lastCols = cols
 521:           entry.lastRows = rows
 522:           entry.pendingResizeOnOpen = false
 523:         }
 524:       } else {
 525:         entry.pendingResizeOnOpen = true
 526:       }
 527:     }
 528: 
 529:     // Deferred refresh: xterm's IntersectionObserver pauses rendering while the
 530:     // terminal element is off-screen. Schedule a second fit+refresh in rAF so
 531:     // the render fires once the observer has cleared the pause.
 532:     const deferredKey = lease.key
 533:     const deferredGen = entry.generation
 534:     window.requestAnimationFrame(() => {
 535:       const e = this.entries.get(deferredKey)
 536:       if (!e || e.generation !== deferredGen || !e.activeContainer) return
 537:       const c = e.activeContainer
 538:       if (c.clientWidth > 0 && c.clientHeight > 0) {
 539:         fitPreservingScroll(e, c, { refreshAfter: true })
 540:       } else {
 541:         try { e.terminal.refresh(0, e.terminal.rows - 1) } catch { /* ignored */ }
 542:       }
 543:     })
 544: 
 545:     // Publish initial snapshot
 546:     callbacks.onConnectionChange(entry.connected)
 547:     callbacks.onCtrlModifierChange(entry.ctrlModifierActive)
 548:     callbacks.onAltModifierChange(entry.altModifierActive)
 549: 
 550:     return lease
 551:   }
 552: 
 553:   checkin(lease: LeaseToken): void {
 554:     const entry = this.entries.get(lease.key)
 555:     if (!entry) return
 556:     if (entry.generation !== lease.generation) return
 557: 
 558:     // Invalidate lease so stale token can't operate after checkin
 559:     entry.generation++
 560: 
 561:     // Mark inactive
 562:     entry.activeCallbacks = null
 563:     entry.activeContainer = null
 564: 
 565:     // Remove foreground listeners
 566:     if (entry.listenerCleanup) {
 567:       entry.listenerCleanup()
 568:       entry.listenerCleanup = null
 569:     }
 570: 
 571:     // Capture dimensions from foreground before moving
 572:     if (entry.terminal.element) {
 573:       entry.lastCols = entry.terminal.cols
 574:       entry.lastRows = entry.terminal.rows
 575:     }
 576: 
 577:     // Move root to hidden host using shared transfer primitive
 578:     const root = entry.terminal.element as HTMLElement | undefined
 579:     if (root) {
 580:       const host = this.ensureHiddenHost(entry)
 581:       const { crossedDocument } = (_transferNode ?? transferNode)(root, host)
 582: 
 583:       // Cross-document reopen
 584:       if (crossedDocument) {
 585:         try { entry.terminal.open(host) } catch { /* ignored */ }
 586:       }
 587:     }
 588:   }
 589: 
 590:   // ── public API: lease-gated operations ──────────────────────────────
 591: 
 592:   fit(lease: LeaseToken): void {
 593:     const entry = this.validateLease(lease)
 594:     if (!entry || !entry.activeContainer) return
 595:     const container = entry.activeContainer
 596:     if (container.clientWidth <= 0 || container.clientHeight <= 0) return
 597:     fitPreservingScroll(entry, container, { refreshAfter: true })
 598:   }
 599: 
 600:   focus(lease: LeaseToken): void {
 601:     const entry = this.validateLease(lease)
 602:     if (!entry) return
 603:     try { entry.terminal.focus() } catch { /* ignored */ }
 604:   }
 605: 
 606:   rehost(lease: LeaseToken, container: HTMLElement, forceRebind?: boolean): void {
 607:     const entry = this.validateLease(lease)
 608:     if (!entry) return
 609: 
 610:     const root = entry.terminal.element as HTMLElement | undefined
 611:     if (!root) return
 612: 
 613:     const { crossedDocument } = (_transferNode ?? transferNode)(root, container)
 614: 
 615:     if (crossedDocument || forceRebind) {
 616:       try { entry.terminal.open(container) } catch { /* ignored */ }
 617:       neutralizeXtermScrollbarFallback(entry.terminal)
 618:     }
 619: 
 620:     entry.activeContainer = container
 621:   }
 622: 
 623:   sendRawBytes(lease: LeaseToken, bytes: Uint8Array): void {
 624:     const entry = this.validateLease(lease)
 625:     if (!entry) return
 626:     const ws = entry.connection.socket
 627:     if (ws && ws.readyState === WebSocket.OPEN) {
 628:       ws.send(bytes)
 629:     }
 630:   }
 631: 
 632:   sendText(lease: LeaseToken, text: string): void {
 633:     if (!text) return
 634:     this.sendRawBytes(lease, new TextEncoder().encode(text))
 635:   }
 636: 
 637:   async sendImage(lease: LeaseToken, file: File, fallbackType: string): Promise<void> {
 638:     const entry = this.validateLease(lease)
 639:     if (!entry) return
 640:     const ws = entry.connection.socket
 641:     if (!ws || ws.readyState !== WebSocket.OPEN) return
 642:     const gen = lease.generation
 643:     try {
 644:       await sendPastedImage(ws, file, fallbackType, entry, gen)
 645:     } catch (err) {
 646:       // Swallow; failed image paste should not crash the terminal.
 647:     }
 648:   }
 649: 
 650:   toggleCtrlModifier(lease: LeaseToken): void {
 651:     const entry = this.validateLease(lease)
 652:     if (!entry) return
 653:     entry.ctrlModifierActive = !entry.ctrlModifierActive
 654:     entry.activeCallbacks?.onCtrlModifierChange(entry.ctrlModifierActive)
 655:   }
 656: 
 657:   clearCtrlModifier(lease: LeaseToken): void {
 658:     const entry = this.validateLease(lease)
 659:     if (!entry) return
 660:     entry.ctrlModifierActive = false
 661:     entry.activeCallbacks?.onCtrlModifierChange(false)
 662:   }
 663: 
 664:   toggleAltModifier(lease: LeaseToken): void {
 665:     const entry = this.validateLease(lease)
 666:     if (!entry) return
 667:     entry.altModifierActive = !entry.altModifierActive
 668:     entry.activeCallbacks?.onAltModifierChange(entry.altModifierActive)
 669:   }
 670: 
 671:   clearAltModifier(lease: LeaseToken): void {
 672:     const entry = this.validateLease(lease)
 673:     if (!entry) return
 674:     entry.altModifierActive = false
 675:     entry.activeCallbacks?.onAltModifierChange(false)
 676:   }
 677: 
 678:   setSelectionMenu(lease: LeaseToken, menu: { x: number; y: number; text: string } | null): void {
 679:     const entry = this.validateLease(lease)
 680:     if (!entry) return
 681:     entry.selectionMenu = menu
 682:     entry.activeCallbacks?.onSelectionMenu(menu)
 683:   }
 684: 
 685:   getTerminalForPaste(lease: LeaseToken): Terminal | null {
 686:     const entry = this.validateLease(lease)
 687:     return entry?.terminal ?? null
 688:   }
 689: 
 690:   // ── public API: preferences ─────────────────────────────────────────
 691: 
 692:   /** Reconcile entry against current prefs (idempotent). Call on checkout. */
 693:   reconcilePrefs(entry: PoolEntry, prefs: TerminalPrefs): void {
 694:     // Theme
 695:     const xtermTheme = getXtermTheme(prefs.theme)
 696:     entry.terminal.options.theme = xtermTheme
 697:     try { entry.terminal.refresh(0, entry.terminal.rows - 1) } catch { /* ignored */ }
 698: 
 699:     // Font
 700:     const fontFamily = `'${prefs.fontFamily}', 'JetBrains Mono', 'Fira Code', Menlo, Monaco, 'Inconsolata LGC Nerd Font Mono', 'DejaVu Sans Mono Symbols', monospace`
 701:     entry.terminal.options.fontSize = prefs.fontSize
 702:     entry.terminal.options.fontFamily = fontFamily
 703:     measureXtermCharSize(entry.terminal)
 704: 
 705:     // Renderer
 706:     if (prefs.renderer === 'webgl' && !entry.webglAddon) {
 707:       const wa = this.factory.createWebglAddon()
 708:       if (wa) {
 709:         wa.onContextLoss(() => {
 710:           wa.dispose()
 711:           entry.webglAddon = null
 712:         })
 713:         try { entry.terminal.loadAddon(wa) } catch { /* ignored */ }
 714:         entry.webglAddon = wa as WebglAddon
 715:       }
 716:     } else if (prefs.renderer === 'dom' && entry.webglAddon) {
 717:       entry.webglAddon.dispose()
 718:       entry.webglAddon = null
 719:     }
 720: 
 721:     // Unicode graphemes
 722:     if (prefs.unicodeGraphemes && !entry.graphemesLoaded) {
 723:       const ga = this.factory.createUnicodeGraphemesAddon()
 724:       if (ga) {
 725:         try { entry.terminal.loadAddon(ga) } catch { /* ignored */ }
 726:         entry.graphemesAddon = ga as UnicodeGraphemesAddon
 727:         entry.graphemesLoaded = true
 728:       }
 729:     } else if (!prefs.unicodeGraphemes && entry.graphemesAddon) {
 730:       entry.graphemesAddon.dispose()
 731:       entry.graphemesAddon = null
 732:       entry.graphemesLoaded = false
 733:     }
 734: 
 735:     // Predictive echo
 736:     if (prefs.predictiveEcho && !entry.predictiveEcho) {
 737:       entry.predictiveEcho = this.factory.createPredictiveEcho(entry.terminal)
 738:     } else if (!prefs.predictiveEcho && entry.predictiveEcho) {
 739:       entry.predictiveEcho.dispose()
 740:       entry.predictiveEcho = null
 741:     }
 742:     entry.predictiveEchoEnabled = prefs.predictiveEcho
 743: 
 744:     entry.appliedPrefs = { ...prefs }
 745:   }
 746: 
 747:   /** Apply prefs to all entries (idempotent). */
 748:   applyGlobalPrefs(prefs: TerminalPrefs): void {
 749:     for (const entry of this.entries.values()) {
 750:       const prevScrollback = entry.appliedPrefs?.scrollback
 751:       const newScrollback = prefs.scrollback
 752: 
 753:       // Scrollback change triggers rebuild
 754:       if (prevScrollback !== undefined && prevScrollback !== newScrollback) {
 755:         // Capture identity before disposal
 756:         const identity = entry.identity
 757:         const key = entry.key
 758:         const wasActive = entry.activeContainer !== null
 759:         const prevContainer = entry.activeContainer
 760: 
 761:         this.disposeEntry(entry)
 762:         this.entries.delete(key)
 763: 
 764:         const newEntry = this.createEntry(key, identity, prefs, this.factory)
 765:         this.entries.set(key, newEntry)
 766: 
 767:         if (wasActive && prevContainer) {
 768:           // Re-checkout into same container
 769:           newEntry.generation++
 770:           newEntry.activeContainer = prevContainer
 771:           const root = newEntry.terminal.element as HTMLElement | undefined
 772:           try { newEntry.terminal.open(prevContainer) } catch { /* ignored */ }
 773:           neutralizeXtermScrollbarFallback(newEntry.terminal)
 774:           if (root) prevContainer.appendChild(root)
 775:           this.attachListeners(newEntry)
 776:           // Load renderer-dependent addons (WebGL) AFTER open() above.
 777:           this.reconcilePrefs(newEntry, prefs)
 778:           fitPreservingScroll(newEntry, prevContainer, { refreshAfter: true })
 779:           // Send resize
 780:           const ws = newEntry.connection.socket
 781:           if (ws && ws.readyState === WebSocket.OPEN) {
 782:             const { cols, rows } = newEntry.terminal
 783:             ws.send(JSON.stringify({ type: 'resize', cols, rows }))
 784:           }
 785:         }
 786:       } else {
 787:         this.reconcilePrefs(entry, prefs)
 788:       }
 789:     }
 790:   }
 791: 
 792:   // ── public API: dispose / rekey ─────────────────────────────────────
 793: 
 794:   dispose(key: string): void {
 795:     const entry = this.entries.get(key)
 796:     if (!entry) return
 797:     this.disposeEntry(entry)
 798:     this.entries.delete(key)
 799:   }
 800: 
 801:   /** Remove entries NOT in validKeys. skip when the server-side catalog is
 802:    *  transient/uncertain (reconnect, empty snapshot) so one stale response
 803:    *  cannot dispose active terminals. */
 804:   disposeAbsent(validKeys: Set<string>, catalogUncertain = false): void {
 805:     if (catalogUncertain) return
 806:     for (const key of this.entries.keys()) {
 807:       if (!validKeys.has(key)) {
 808:         this.dispose(key)
 809:       }
 810:     }
 811:   }
 812: 
 813:   /** Rename a pool entry, preserving terminal/WS. */
 814:   rekey(oldKey: string, newKey: string): void {
 815:     if (oldKey === newKey) return
 816:     const entry = this.entries.get(oldKey)
 817:     if (!entry) return
 818: 
 819:     // Dispose destination if it exists
 820:     if (this.entries.has(newKey)) {
 821:       this.dispose(newKey)
 822:     }
 823: 
 824:     // Move entry to new key
 825:     this.entries.delete(oldKey)
 826:     const sessionName = newKey.includes('/') ? newKey.slice(newKey.indexOf('/') + 1) : newKey
 827:     const hostId = newKey.includes('/') ? newKey.slice(0, newKey.indexOf('/')) : undefined
 828:     const prev = entry.identity
 829:     entry.key = newKey
 830:     // Canonical identity is immutable (`sessionId`/`ownerId`/`generation`); a
 831:     // label change must NOT mutate them, so preserve them across a rename and
 832:     // only update the display key fields.
 833:     entry.identity = {
 834:       sessionName,
 835:       hostId,
 836:       backend: prev.backend,
 837:       sessionId: prev.sessionId,
 838:       ownerId: prev.ownerId,
 839:       generation: prev.generation,
 840:     }
 841:     // Update the lease token for current owner
 842:     entry.generation++ // invalidate previous lease
 843:     this.entries.set(newKey, entry)
 844:   }
 845: 
 846:   /**
 847:    * Reconnect an existing pool entry in place after its daemon generation
 848:    * changed (recovery/restart). Same terminal instance, scrollback, and lease
 849:    * are preserved; only the WebSocket URL is rebuilt with the new generation.
 850:    * No-op for unknown keys or when the generation is unchanged.
 851:    */
 852:   updateGeneration(key: string, generation: string): void {
 853:     const entry = this.entries.get(key)
 854:     if (!entry || entry.identity.generation === generation) return
 855:     entry.identity = { ...entry.identity, generation }
 856:     entry.connection.connect(this.buildUrl({ key, identity: entry.identity }))
 857:   }
 858: 
 859:   /** Reset all state (for tests). */
 860:   reset(): void {
 861:     for (const entry of this.entries.values()) {
 862:       this.disposeEntry(entry)
 863:     }
 864:     this.entries.clear()
 865:     if (this.poolRoot) {
 866:       this.poolRoot.remove()
 867:       this.poolRoot = null
 868:     }
 869:     _transferNode = null
 870:   }
 871: 
 872:   // ── private helpers ─────────────────────────────────────────────────
 873: 
 874:   private validateLease(lease: LeaseToken): PoolEntry | null {
 875:     const entry = this.entries.get(lease.key)
 876:     if (!entry || entry.generation !== lease.generation) return null
 877:     return entry
 878:   }
 879: 
 880:   private ensureHiddenHost(entry: PoolEntry): HTMLElement {
 881:     if (entry.hiddenHost) return entry.hiddenHost
 882: 
 883:     if (!this.poolRoot) {
 884:       const root = document.createElement('div')
 885:       root.setAttribute('data-terminal-pool-root', '')
 886:       root.style.position = 'fixed'
 887:       root.style.top = '-9999px'
 888:       root.style.left = '-9999px'
 889:       root.style.width = '1px'
 890:       root.style.height = '1px'
 891:       root.style.overflow = 'hidden'
 892:       root.style.pointerEvents = 'none'
 893:       root.style.visibility = 'visible' // NOT display:none — keep rAF/WebGL alive
 894:       root.style.opacity = '0'
 895:       document.body.appendChild(root)
 896:       this.poolRoot = root
 897:     }
 898: 
 899:     const host = document.createElement('div')
 900:     host.setAttribute('data-terminal-pool-host', entry.key)
 901:     host.style.width = `${Math.max(entry.lastCols * 10, 80)}px`
 902:     host.style.height = `${Math.max(entry.lastRows * 18, 24)}px`
 903:     host.style.pointerEvents = 'none'
 904:     host.style.overflow = 'hidden'
 905:     host.style.visibility = 'visible'
 906:     this.poolRoot.appendChild(host)
 907:     entry.hiddenHost = host
 908:     return host
 909:   }
 910: 
 911:   // ── entry creation ──────────────────────────────────────────────────
 912: 
 913:   private createEntry(
 914:     key: string,
 915:     identity: PoolIdentity,
 916:     prefs: TerminalPrefs,
 917:     ef: PoolFactory,
 918:   ): PoolEntry {
 919:     const xtermTheme = getXtermTheme(prefs.theme)
 920:     const fontFamily = `'${prefs.fontFamily}', 'JetBrains Mono', 'Fira Code', Menlo, Monaco, 'Inconsolata LGC Nerd Font Mono', 'DejaVu Sans Mono Symbols', monospace`
 921: 
 922:     const term = ef.createTerminal({
 923:       theme: xtermTheme,
 924:       fontSize: prefs.fontSize,
 925:       fontFamily,
 926:       cursorBlink: true,
 927:       scrollback: prefs.scrollback,
 928:       allowProposedApi: true,
 929:       rightClickSelectsWord: true,
 930:       macOptionClickForcesSelection: true,
 931:       macOptionIsMeta: true,
 932:     })
 933: 
 934:     const fitAddon = ef.createFitAddon()
 935:     term.loadAddon(fitAddon)
 936:     term.loadAddon(ef.createWebLinksAddon())
 937:     term.loadAddon(ef.createClipboardAddon(clipboardProvider))
 938: 
 939:     // WebGL renderer is loaded lazily AFTER term.open() (xterm.js requirement).
 940:     let webglAddon: WebglAddon | null = null
 941: 
 942:     const imageAddon = ef.createImageAddon()
 943:     if (imageAddon) {
 944:       try { term.loadAddon(imageAddon) } catch { /* ignored */ }
 945:     }
 946: 
 947:     let graphemesAddon: UnicodeGraphemesAddon | null = null
 948:     let graphemesLoaded = false
 949:     if (prefs.unicodeGraphemes) {
 950:       const ga = ef.createUnicodeGraphemesAddon()
 951:       if (ga) {
 952:         try { term.loadAddon(ga) } catch { /* ignored */ }
 953:         graphemesAddon = ga as UnicodeGraphemesAddon
 954:         graphemesLoaded = true
 955:       }
 956:     }
 957: 
 958:     let predictiveEcho: PredictiveEcho | null = null
 959:     if (prefs.predictiveEcho) {
 960:       predictiveEcho = ef.createPredictiveEcho(term)
 961:     }
 962: 
 963:     const replayBuffer = new ReplayBuffer()
 964: 
 965:     // eslint-disable-next-line prefer-const
 966:     let entry!: PoolEntry
 967: 
 968:     const connection = new ConnectionMachine(
 969:       {
 970:         createWebSocket: ef.createWebSocket,
 971:         onConnecting: () => {
 972:           entry.replayBuffer.reset()
 973:           entry.syncActive = false
 974:           entry.syncBuffer = []
 975:           entry.syncCarryover = null
 976:         },
 977:         onConnectionChange: (connected) => this.handleConnectionChange(entry, connected),
 978:         onOpen: () => this.handleOpen(entry),
 979:         onBinaryMessage: (data) => this.handleBinaryMessage(entry, data),
 980:         onTextMessage: (text) => this.handleTextControl(entry, text),
 981:         onReplayStart: () => {
 982:           entry.replayBuffer.reset()
 983:           entry.syncActive = false
 984:           entry.syncBuffer = []
 985:           entry.syncCarryover = null
 986:         },
 987:         onReplayEnd: () => this.flushReplayBuffer(entry),
 988:         onFallback: () => this.flushReplayBuffer(entry),
 989:       },
 990:       this.buildUrl({ key, identity }),
 991:     )
 992: 
 993:     entry = {
 994:       key,
 995:       identity,
 996: 
 997:       terminal: term,
 998:       fitAddon,
 999:       webglAddon,
1000:       imageAddon,
1001:       graphemesAddon,
1002:       graphemesLoaded,
1003:       predictiveEcho,
1004:       predictiveEchoEnabled: prefs.predictiveEcho,
1005: 
1006:       connection,
1007:       replayBuffer,
1008: 
1009:       connected: false,
1010: 
1011:       generation: 0,
1012:       fitEpoch: 0,
1013:       userScrolled: false,
1014: 
1015:       activeContainer: null,
1016:       activeCallbacks: null,
1017:       listenerCleanup: null,
1018: 
1019:       hiddenHost: null,
1020: 
1021:       lastCols: 0,
1022:       lastRows: 0,
1023:       pendingResizeOnOpen: false,
1024: 
1025:       ctrlModifierActive: false,
1026:       altModifierActive: false,
1027:       suppressedInput: null,
1028: 
1029:       selectionMenu: null,
1030: 
1031:       appliedPrefs: { ...prefs },
1032: 
1033:       syncCarryover: null,
1034:       syncActive: false,
1035:       syncBuffer: [],
1036: 
1037:       writePending: false,
1038:     }
1039: 
1040:     connection.connect()
1041:     return entry
1042:   }
1043: 
1044:   // ── connection event handlers ───────────────────────────────────────
1045: 
1046:   private buildUrl(target: { key: string; identity: PoolIdentity }): string {
1047:     const term = this.entries.get(target.key)?.terminal
1048:     const cols = term?.cols || 80
1049:     const rows = term?.rows || 24
1050: 
1051:     const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
1052:     const sessionName = target.identity.sessionName
1053:     const hostId = target.identity.hostId
1054:     const backend = target.identity.backend
1055: 
1056:     const hostParam = hostId ? `&host=${encodeURIComponent(hostId)}` : ''
1057:     if (backend === 'daemon') {
1058:       // The legacy `name` param (display label) is required by the remote/
1059:       // peer routing path (handleRemoteSession) and doubles as the daemon key
1060:       // for pre-v2 sessions. The immutable SessionID is emitted only when it
1061:       // is actually known (a real v2 stable id) so legacy display names that
1062:       // are not valid SessionIDs keep routing by name.
1063:       const idParam = target.identity.sessionId
1064:         ? `&sessionID=${encodeURIComponent(target.identity.sessionId)}`
1065:         : ''
1066:       const genParam = target.identity.generation
1067:         ? `&generation=${encodeURIComponent(target.identity.generation)}`
1068:         : ''
1069:       return `${protocol}//${window.location.host}/ws/daemon-session?name=${encodeURIComponent(sessionName)}${idParam}${genParam}&cols=${cols}&rows=${rows}${hostParam}&replay=1`
1070:     }
1071:     if (sessionName.startsWith('direct-pty:')) {
1072:       return `${protocol}//${window.location.host}/ws/direct-session?cols=${cols}&rows=${rows}`
1073:     }
1074:     return `${protocol}//${window.location.host}/ws/session?name=${encodeURIComponent(sessionName)}&cols=${cols}&rows=${rows}${hostParam}&replay=1`
1075:   }
1076: 
1077:   private handleConnectionChange(entry: PoolEntry, connected: boolean): void {
1078:     entry.connected = connected
1079:     if (connected) {
1080:       entry.activeCallbacks?.onConnectionChange(true)
1081:       return
1082:     }
1083:     // Suppress the disconnected overlay while the tab is hidden; the machine
1084:     // will reconnect automatically when visibility returns.
1085:     if (!document.hidden) {
1086:       entry.activeCallbacks?.onConnectionChange(false)
1087:     }
1088:   }
1089: 
1090:   private handleOpen(entry: PoolEntry): void {
1091:     entry.syncActive = false
1092:     entry.syncBuffer = []
1093:     entry.syncCarryover = null
1094:     entry.writePending = false
1095: 
1096:     const ws = entry.connection.socket
1097:     if (entry.pendingResizeOnOpen && entry.activeContainer && ws) {
1098:       entry.pendingResizeOnOpen = false
1099:       const c = entry.terminal.cols
1100:       const r = entry.terminal.rows
1101:       entry.lastCols = c
1102:       entry.lastRows = r
1103:       try { ws.send(JSON.stringify({ type: 'resize', cols: c, rows: r })) } catch { /* ignored */ }
1104:     }
1105:   }
1106: 
1107:   private handleBinaryMessage(entry: PoolEntry, data: Uint8Array): void {
1108:     if (entry.connection.state === 'replaying') {
1109:       const flush = entry.replayBuffer.add(data)
1110:       if (flush) {
1111:         this.writeRaw(entry, flush.bytes)
1112:         entry.connection.markLive()
1113:       }
1114:       return
1115:     }
1116: 
1117:     this.dispatchLiveOutput(entry, data)
1118:   }
1119: 
1120:   private handleTextControl(entry: PoolEntry, text: string): void {
1121:     let ctrl: { type?: string } | null = null
1122:     try {
1123:       ctrl = JSON.parse(text)
1124:     } catch {
1125:       // Not JSON; write the raw string below.
1126:     }
1127: 
1128:     if (ctrl && ctrl.type === 'pong') return
1129:     if (ctrl && ctrl.type === 'replay-start') {
1130:       entry.connection.startReplay()
1131:       return
1132:     }
1133:     if (ctrl && ctrl.type === 'replay-end') {
1134:       entry.connection.endReplay()
1135:       return
1136:     }
1137: 
1138:     // Non-control string (or unknown control): write directly.
1139:     this.writeRaw(entry, text)
1140:   }
1141: 
1142:   private flushReplayBuffer(entry: PoolEntry): void {
1143:     const all = entry.replayBuffer.flush()
1144:     if (all) {
1145:       this.writeRaw(entry, all)
1146:     }
1147:   }
1148: 
1149:   // Replay / non-control output: no latency measurement; just write and scroll.
1150:   private writeRaw(entry: PoolEntry, data: Uint8Array | string): void {
1151:     entry.predictiveEcho?.clear()
1152:     entry.terminal.write(data, () => {
1153:       if (!entry.userScrolled) {
1154:         try { entry.terminal.scrollToBottom() } catch { /* ignored */ }
1155:       }
1156:     })
1157:   }
1158: 
1159:   // ── live output dispatcher (BSU/ESU) ────────────────────────────────
1160: 
1161:   // Live output dispatcher. Handles DEC mode 2026 synchronized-update
1162:   // markers (BSU/ESU) by buffering bytes between markers and flushing them
1163:   // as a single terminal.write. Markers are stripped. Straddling markers are
1164:   // handled via syncCarryover.
1165:   private dispatchLiveOutput(entry: PoolEntry, data: Uint8Array): void {
1166:     if (entry.syncCarryover !== null) {
1167:       data = concatU8Legacy([entry.syncCarryover, data])
1168:       entry.syncCarryover = null
1169:     }
1170: 
1171:     const out: Uint8Array[] = []
1172:     let cursor = 0
1173: 
1174:     while (cursor < data.length) {
1175:       const idx = indexOfU8(data, SYNC_MARKER_PREFIX, cursor)
1176:       if (idx === -1) {
1177:         const rest = data.subarray(cursor)
1178:         const tail = this.findSyncMarkerPrefixTail(rest)
1179:         if (tail !== null) {
1180:           if (tail.length < rest.length) {
1181:             out.push(rest.subarray(0, rest.length - tail.length))
1182:           }
1183:           entry.syncCarryover = tail
1184:         } else {
1185:           out.push(rest)
1186:         }
1187:         cursor = data.length
1188:         break
1189:       }
1190: 
1191:       if (idx + SYNC_MARKER_PREFIX.length >= data.length) {
1192:         // Marker prefix runs right up to (or past) the end; carry the whole
1193:         // tail over to the next chunk.
1194:         out.push(data.subarray(cursor, idx))
1195:         entry.syncCarryover = data.subarray(idx)
1196:         cursor = data.length
1197:         break
1198:       }
1199: 
1200:       const markerByte = data[idx + SYNC_MARKER_PREFIX.length]
1201:       if (markerByte !== 0x68 && markerByte !== 0x6c) {
1202:         // Looks like the prefix but is not a valid BSU/ESU; treat as ordinary
1203:         // bytes and continue scanning after the prefix.
1204:         out.push(data.subarray(cursor, idx + SYNC_MARKER_PREFIX.length))
1205:         cursor = idx + SYNC_MARKER_PREFIX.length
1206:         continue
1207:       }
1208: 
1209:       // Slice before the marker.
1210:       if (idx > cursor) {
1211:         out.push(data.subarray(cursor, idx))
1212:       }
1213: 
1214:       if (markerByte === 0x68) {
1215:         // Begin Synchronized Update.
1216:         this.flushLiveSlices(entry, out)
1217:         out.length = 0
1218:         entry.syncActive = true
1219:         entry.syncBuffer = []
1220:       } else {
1221:         // End Synchronized Update.
1222:         if (entry.syncActive) {
1223:           if (out.length) {
1224:             entry.syncBuffer.push(...out)
1225:             out.length = 0
1226:           }
1227:           const all = concatU8Legacy(entry.syncBuffer)
1228:           entry.predictiveEcho?.clear()
1229:           entry.terminal.write(all, () => {
1230:             if (!entry.userScrolled) {
1231:               try { entry.terminal.scrollToBottom() } catch { /* ignored */ }
1232:             }
1233:           })
1234:           entry.syncBuffer = []
1235:           entry.syncActive = false
1236:         }
1237:         // ESU without matching BSU is a no-op; marker stripped.
1238:       }
1239: 
1240:       cursor = idx + SYNC_MARKER_PREFIX.length + 1
1241:     }
1242: 
1243:     this.flushLiveSlices(entry, out)
1244:   }
1245: 
1246:   private flushLiveSlices(entry: PoolEntry, slices: Uint8Array[]): void {
1247:     if (slices.length === 0) return
1248:     const data = concatU8Legacy(slices)
1249:     slices.length = 0
1250:     if (entry.syncActive) {
1251:       entry.syncBuffer.push(data)
1252:       return
1253:     }
1254:     this.writeLiveRaw(entry, data)
1255:   }
1256: 
1257:   private writeLiveRaw(entry: PoolEntry, data: Uint8Array): void {
1258:     entry.predictiveEcho?.clear()
1259:     const hadPending = entry.writePending
1260:     entry.writePending = false
1261:     entry.terminal.write(data, () => {
1262:       if (hadPending) {
1263:         entry.writePending = false
1264:       }
1265:       if (!entry.userScrolled) {
1266:         try { entry.terminal.scrollToBottom() } catch { /* ignored */ }
1267:       }
1268:     })
1269:   }
1270: 
1271:   private findSyncMarkerPrefixTail(data: Uint8Array): Uint8Array | null {
1272:     const marker = SYNC_MARKER_PREFIX
1273:     const max = Math.min(data.length, marker.length - 1)
1274:     for (let len = max; len >= 1; len--) {
1275:       let ok = true
1276:       for (let i = 0; i < len; i++) {
1277:         if (data[data.length - len + i] !== marker[i]) {
1278:           ok = false
1279:           break
1280:         }
1281:       }
1282:       if (ok) return data.subarray(data.length - len)
1283:     }
1284:     return null
1285:   }
1286: 
1287:   // ── foreground listeners ────────────────────────────────────────────
1288: 
1289:   private attachListeners(entry: PoolEntry): void {
1290:     const container = entry.activeContainer
1291:     if (!container) return
1292: 
1293:     const term = entry.terminal
1294: 
1295:     // Open terminal into container
1296:     try { term.open(container) } catch { /* ignored */ }
1297:     neutralizeXtermScrollbarFallback(term)
1298: 
1299:     const helperTextarea = container.querySelector('textarea.xterm-helper-textarea') as HTMLTextAreaElement | null
1300: 
1301:     requestClipboardPermission()
1302: 
1303:     // Custom key handler
1304:     term.attachCustomKeyEventHandler((e) => {
1305:       if (e.type === 'keydown') flushPendingClipboard()
1306:       if (
1307:         e.type === 'keydown' &&
1308:         entry.ctrlModifierActive &&
1309:         !e.metaKey && !e.ctrlKey && !e.altKey &&
1310:         e.key.length === 1
1311:       ) {
1312:         const key = e.key.toUpperCase()
1313:         if (key >= 'A' && key <= 'Z') {
1314:           entry.suppressedInput = e.key
1315:           this.sendRawBytes(
1316:             { generation: entry.generation, key: entry.key },
1317:             new Uint8Array([key.charCodeAt(0) - 64]),
1318:           )
1319:           entry.ctrlModifierActive = false
1320:           entry.activeCallbacks?.onCtrlModifierChange(false)
1321:           return false
1322:         }
1323:       }
1324:       if (
1325:         e.type === 'keydown' &&
1326:         entry.altModifierActive &&
1327:         !e.metaKey && !e.ctrlKey && !e.altKey &&
1328:         e.key.length === 1
1329:       ) {
1330:         entry.suppressedInput = e.key
1331:         this.sendRawBytes(
1332:           { generation: entry.generation, key: entry.key },
1333:           new Uint8Array([0x1b, ...new TextEncoder().encode(e.key)]),
1334:         )
1335:         entry.altModifierActive = false
1336:         entry.activeCallbacks?.onAltModifierChange(false)
1337:         return false
1338:       }
1339:       if (e.type === 'keydown' && (e.metaKey || e.ctrlKey)) {
1340:         const key = e.key.toLowerCase()
1341:         if (!e.shiftKey) {
1342:           if (key === ',' || key === '\\' || key === '/' || key === '?') return false
1343:         } else {
1344:           if (key === '/' || key === '?' || key === '\\' || key === 'k' ||
1345:               key === 'enter' || key === 'h' || key === 'f' || key === 'g' ||
1346:               e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
1347:             return false
1348:           }
1349:         }
1350:       }
1351:       if ((e.metaKey || e.ctrlKey) && e.key === 'c' && e.type === 'keydown') {
1352:         const selection = term.getSelection()
1353:         if (selection) {
1354:           navigator.clipboard?.writeText(normalizeSelection(selection))
1355:           term.clearSelection()
1356:           return false
1357:         }
1358:         this.sendRawBytes(
1359:           { generation: entry.generation, key: entry.key },
1360:           new Uint8Array([0x03]),
1361:         )
1362:         return false
1363:       }
1364:       if ((e.metaKey || e.ctrlKey) && e.key === 'b' && e.type === 'keydown') {
1365:         this.sendRawBytes(
1366:           { generation: entry.generation, key: entry.key },
1367:           new Uint8Array([0x02]),
1368:         )
1369:         return false
1370:       }
1371:       return true
1372:     })
1373: 
1374:     // Selection change -> auto copy
1375:     term.onSelectionChange(() => {
1376:       const selection = term.getSelection()
1377:       if (selection) {
1378:         copyToClipboard(selection)
1379:       }
1380:     })
1381: 
1382:     // Mouse/keyboard for clipboard flush
1383:     const onMouseDown = (e: MouseEvent) => {
1384:       flushPendingClipboard()
1385:       if (e.button === 2 && term.getSelection()) {
1386:         e.preventDefault()
1387:         e.stopPropagation()
1388:         e.stopImmediatePropagation()
1389:       }
1390:     }
1391:     const onKeyDown = () => flushPendingClipboard()
1392:     const onWindowKeyDownCapture = (e: KeyboardEvent) => {
1393:       if (!(e.metaKey || e.ctrlKey) || e.key.toLowerCase() !== 'b') return
1394:       const active = document.activeElement
1395:       const terminalFocused = !!active && (container.contains(active) || active === container)
1396:       if (!terminalFocused) return
1397:       e.preventDefault()
1398:       e.stopPropagation()
1399:       this.sendRawBytes(
1400:         { generation: entry.generation, key: entry.key },
1401:         new Uint8Array([0x02]),
1402:       )
1403:     }
1404:     const onPaste = (e: ClipboardEvent) => {
1405:       const items = Array.from(e.clipboardData?.items ?? [])
1406:       const imageItem = items.find(item => item.type.startsWith('image/'))
1407:       if (!imageItem) {
1408:         // Chrome 150+ strips file/image data from paste events whose target is
1409:         // a hidden editable, so fall back to the async Clipboard API.
1410:         if (items.length === 0 && navigator.clipboard?.read) {
1411:           const currentWs = entry.connection.socket
1412:           if (!currentWs || currentWs.readyState !== WebSocket.OPEN) return
1413:           const gen = entry.generation
1414:           navigator.clipboard.read().then(async (clipItems) => {
1415:             for (const item of clipItems) {
1416:               const imageType = item.types.find(t => t.startsWith('image/'))
1417:               if (!imageType) continue
1418:               const blob = await item.getType(imageType)
1419:               const ext = imageType.split('/')[1]?.split('+')[0] || 'png'
1420:               const file = new File([blob], `pasted-image.${ext}`, { type: imageType })
1421:               await sendPastedImage(currentWs, file, imageType, entry, gen)
1422:               return
1423:             }
1424:           }).catch(() => { /* no permission or no image — nothing to paste */ })
1425:         }
1426:         return
1427:       }
1428:       const file = imageItem.getAsFile()
1429:       const currentWs = entry.connection.socket
1430:       if (!file || !currentWs || currentWs.readyState !== WebSocket.OPEN) return
1431:       e.preventDefault()
1432:       const gen = entry.generation
1433:       sendPastedImage(currentWs, file, imageItem.type, entry, gen).catch(() => {
1434:         // Failed image paste is non-fatal.
1435:       })
1436:     }
1437:     const onContextMenu = (e: MouseEvent) => {
1438:       e.preventDefault()
1439:       const sel = term.getSelection()
1440:       if (sel) {
1441:         const menu = { x: e.clientX, y: e.clientY, text: normalizeSelection(sel) }
1442:         entry.selectionMenu = menu
1443:         entry.activeCallbacks?.onSelectionMenu(menu)
1444:       }
1445:     }
1446: 
1447:     // User took over the viewport.
1448:     const markUserScroll = () => {
1449:       if (!entry.userScrolled) {
1450:         entry.userScrolled = true
1451:         entry.fitEpoch++
1452:       }
1453:     }
1454:     const onViewportScroll = () => {
1455:       if (!entry.userScrolled || !vpEl) return
1456:       if (vpEl.scrollTop + vpEl.clientHeight >= vpEl.scrollHeight - 2) {
1457:         entry.userScrolled = false
1458:       }
1459:     }
1460:     const onWheel = () => markUserScroll()
1461:     const vpEl = container.querySelector('.xterm-viewport') as HTMLElement | null
1462:     vpEl?.addEventListener('scroll', onViewportScroll, { passive: true })
1463:     container.addEventListener('wheel', onWheel, { passive: true })
1464:     container.addEventListener('touchmove', markUserScroll, { passive: true })
1465: 
1466:     container.addEventListener('mousedown', onMouseDown, true)
1467:     container.addEventListener('keydown', onKeyDown, true)
1468:     window.addEventListener('keydown', onWindowKeyDownCapture, true)
1469:     helperTextarea?.addEventListener('paste', onPaste)
1470:     container.addEventListener('contextmenu', onContextMenu)
1471: 
1472:     // onData handler
1473:     const onDataDispose = term.onData((data) => {
1474:       if (!entry.activeCallbacks || !entry.activeContainer) return
1475: 
1476:       if (entry.suppressedInput !== null && data === entry.suppressedInput) {
1477:         entry.suppressedInput = null
1478:         return
1479:       }
1480:       entry.suppressedInput = null
1481:       const ws = entry.connection.socket
1482:       if (ws && ws.readyState === WebSocket.OPEN) {
1483:         let payload = data
1484:         if (
1485:           data.length > 1 &&
1486:           !data.startsWith('\x1b[200~') &&
1487:           (data.includes('\r') || data.includes('\n'))
1488:         ) {
1489:           payload = '\x1b[200~' + data + '\x1b[201~'
1490:         }
1491:         const encoder = new TextEncoder()
1492:         if (data.length === 1) {
1493:           const code = data.charCodeAt(0)
1494:           if (code >= 0x20 && code <= 0x7e) {
1495:             if (!entry.writePending) {
1496:               entry.writePending = true
1497:             }
1498:           }
1499:         }
1500:         let pe = entry.predictiveEcho
1501:         if (!pe && entry.predictiveEchoEnabled) {
1502:           pe = this.factory.createPredictiveEcho(entry.terminal)
1503:           entry.predictiveEcho = pe
1504:         }
1505:         if (pe && entry.predictiveEchoEnabled) {
1506:           if (pe.canPredict(data)) {
1507:             pe.predict(data)
1508:           } else {
1509:             pe.clear()
1510:           }
1511:         }
1512:         ws.send(encoder.encode(payload))
1513:       }
1514:     })
1515: 
1516:     // onResize handler — only while checked out
1517:     const onResizeDispose = term.onResize(({ cols, rows }) => {
1518:       if (!entry.activeContainer) return
