  64:   // /session/<host>/<name> or /session/<name> (backward compat)
  65:   const hostMatch = window.location.pathname.match(/^\/session\/([^/]+)\/(.+)$/)
  66:   if (hostMatch) {
  67:     const host = decodeURIComponent(hostMatch[1])
  68:     const name = decodeURIComponent(hostMatch[2])
  69:     return { view: 'session', sessionKey: `${host}/${name}` }
  70:   }
  71:   const match = window.location.pathname.match(/^\/session\/(.+)$/)
  72:   if (match) {
  73:     return { view: 'session', sessionKey: decodeURIComponent(match[1]) }
  74:   }
  75:   return { view: 'overview', sessionKey: null }
  76: }
