 464:       if (skeys.length === 0) return
 465:       const current = selectedSessionRef.current
 466:       const idx = current ? skeys.indexOf(current) : -1
 467:       const nextIdx =
 468:         dir === 1
 469:           ? idx >= 0
 470:             ? (idx + 1) % skeys.length
 471:             : 0
 472:           : idx > 0
 473:             ? idx - 1
 474:             : skeys.length - 1
 475:       const targetKey = skeys[nextIdx]
 476:       // If target belongs to a saved group, switch to that group first
 477:       const group = Object.entries(syncedGroupsRef.current).find(([, g]) => findLeaf(g.tree, targetKey))
 478:       if (group) {
 479:         const [groupId] = group
 480:         switchToGroupRef.current?.(groupId)
 481:         setActiveKeyRef.current(targetKey)
 482:         const { host, name } = parseSessionKey(targetKey)
 483:         const path = host
 484:           ? `/session/${encodeURIComponent(host)}/${encodeURIComponent(name)}`
 485:           : `/session/${encodeURIComponent(name)}`
