 498:     // The terminal owns the keyboard. useTerminal() (attachCustomKeyEventHandler)
 499:     // already decides which $mod combos escape xterm and bubble here — that
 500:     // narrow whitelist IS the gate. So we must NOT let tinykeys' default ignore
 501:     // drop events originating from the xterm helper textarea, or whitelisted
 502:     // shortcuts would silently fail while a session is focused. Other form
 503:     // inputs (modals, settings) keep the default ignore behaviour.
 504:     const ignore = (e: KeyboardEvent) => {
 505:       const target = e.target as HTMLElement | null
