 963:     if (!worktreeBranch) setNewSessionModalOpen(false)
 964: 
 965:     // Optimistic: render sidebar stub + mount terminal instantly. Resolved
 966:     // name may differ from the requested name if the server dedups, so we
 967:     // migrate the session key once the POST resolves.
 968:     const optimisticKey = hostId ? `${hostId}/${name}` : name
 969:     if (!worktreeBranch) {
 970:       pendingSessionRef.current = optimisticKey
 971:       const fallbackPending = optimisticKey
 972:       window.setTimeout(() => {
 973:         if (pendingSessionRef.current === fallbackPending) pendingSessionRef.current = null
 974:       }, 15000)
 975:       workspaceActions.addOptimistic(optimisticSession(name, hostId || localHostId, localHostName, path))
 976:     }
 977: 
 978:     // Apply the split/single layout with the optimistic key now, so the pane
 979:     // mounts in parallel with the backend create.
 980:     const target = splitTarget ?? splitTargetRef.current
 981:     splitTargetRef.current = null
 982:     if (!worktreeBranch) {
 983:       if (target) {
 984:         workspaceActions.splitPane(target.key, target.direction, optimisticKey, target.newFirst)
 985:       } else {
 986:         selectSession(optimisticKey)
 987:       }
 988:       setTimeout(() => refocusTerminal(), 0)
 989:     }
 990: 
 991:     try {
 992:       // v2 slice: route creation through the typed session-command endpoint
 993:       // when enabled, instead of the legacy per-field create call. Only the
 994:       // create action is migrated so far -- everything else below (optimistic
 995:       // stub, pane placement, reconciliation) is unchanged.
 996:       let resolvedName: string
 997:       if (v2Enabled && !hostId) {
 998:         try {
 999:           const result = await v2State.createSession({ name, shell: command || undefined, cwd: path, worktreeBranch: worktreeBranch || undefined, layoutId: target ? (v2State.layoutId ?? undefined) : undefined })
1000:           const r = result as { Ref?: { owner?: string | null; session?: string; window?: number; pane?: number }; DisplayName?: string } | null
1001:           resolvedName = r?.Ref?.session || r?.DisplayName || name
1002:           if (target && v2State.layoutId && r?.Ref?.session) {
1003:             const newRef: SessionRef = {
1004:               owner: r.Ref.owner ?? null,
1005:               session: r.Ref.session,
1006:               window: r.Ref.window ?? 0,
1007:               pane: r.Ref.pane ?? 0,
1008:             }
1009:             void v2State.workspaceCommand(v2State.layoutId, {
1010:               action: 'split',
1011:               target: keyToSessionRef(target.key),
1012:               direction: target.direction,
1013:               new: newRef,
1014:               new_first: target.newFirst,
1015:             }).catch(err => console.error('v2 split command failed:', err))
1016:           }
1017:         } catch (err) {
1018:           if (!worktreeBranch) {
1019:             workspaceActions.removeOptimistic(name, hostId || localHostId)
1020:             if (pendingSessionRef.current === optimisticKey) pendingSessionRef.current = null
1021:           }
1022:           if (worktreeBranch) {
1023:             return err instanceof Error ? err.message : 'Failed to create worktree'
1024:           }
1025:           return null
1026:         }
1027:         if (worktreeBranch) setNewSessionModalOpen(false)
1028:       } else {
1029:         const res = await fetch('/api/session/new', {
1030:           method: 'POST',
1031:           headers: { 'Content-Type': 'application/json' },
1032:           body: JSON.stringify({ name, path, command, host: hostId || undefined, agent_type: agentType || undefined, worktree_branch: worktreeBranch || undefined }),
1033:         })
1034:         if (!res.ok) {
1035:           if (!worktreeBranch) {
1036:             workspaceActions.removeOptimistic(name, hostId || localHostId)
1037:             if (pendingSessionRef.current === optimisticKey) pendingSessionRef.current = null
1038:           }
1039:           if (worktreeBranch) {
1040:             const msg = await res.text().catch(() => 'Failed to create worktree')
1041:             return msg
1042:           }
1043:           return null
1044:         }
1045:         if (worktreeBranch) setNewSessionModalOpen(false)
1046:         const payload = await res.json().catch(() => null)
1047:         resolvedName = payload?.name || name
