1049:       if (resolvedName !== name && !worktreeBranch) {
1050:         // Server deduped the name — migrate the optimistic key to the real one.
1051:         // Don't upsert a fresh stub: the real record is already on its way via
1052:         // the server's session-added broadcast; just protect it from pruning.
1053:         const resolvedKey = hostId ? `${hostId}/${resolvedName}` : resolvedName
1054:         workspaceActions.removeOptimistic(name, hostId || localHostId)
1055:         workspaceActions.renameSession(optimisticKey, resolvedKey)
1056:         pendingSessionRef.current = resolvedKey
1057:       }
1058:       // Reconcile with the real server record; clears the optimistic stub.
1059:       workspaceActions.refresh()
1060:     } catch (err) {
1061:       console.error('Failed to create session:', err)
1062:       if (!worktreeBranch) {
1063:         workspaceActions.removeOptimistic(name, hostId || localHostId)
1064:         if (pendingSessionRef.current === optimisticKey) pendingSessionRef.current = null
1065:       }
1066:     }
1067:     return null
1068:   }, [selectSession, refocusTerminal, localHostId, localHostName, workspaceActions, v2Enabled, v2State])
1069: 
1070:   const handleQuickShell = useCallback(() => {
1071:     const name = `shell-${Date.now()}`
