1073:     // Optimistic: fire the backend create first (non-awaited) so the daemon
1074:     // starts spawning immediately, then render the sidebar stub + mount the
1075:     // terminal. The Terminal pool's WS connect retries while NewDaemonSession
1076:     // (server-side) retries the dial until the socket is ready.
1077:     fetch('/api/session/new', {
1078:       method: 'POST',
1079:       headers: { 'Content-Type': 'application/json' },
1080:       body: JSON.stringify({ name, path: '', command: '', backend: 'daemon' }),
1081:     }).then(res => {
1082:       if (!res.ok) {
1083:         workspaceActions.removeOptimistic(name, localHostId)
1084:         if (pendingSessionRef.current === sk) pendingSessionRef.current = null
1085:       } else {
