1089:     }).catch(() => {
1090:       workspaceActions.removeOptimistic(name, localHostId)
1091:       if (pendingSessionRef.current === sk) pendingSessionRef.current = null
1092:     })
1093:     pendingSessionRef.current = sk
1094:     workspaceActions.addOptimistic(optimisticSession(name, localHostId, localHostName))
