1101:   const handleDropNewSession = useCallback((targetKey: string, edge: 'left'|'right'|'top'|'bottom'|'center') => {
1102:     // Fall back to the first pane when a split is visible but no active pane is
1103:     // set, so a drop that lands on the container (not a pane) still splits
1104:     // instead of silently spawning a standalone session ("refuse to split").
1105:     let key = targetKey || activeKey || (paneTree ? getLeaves(paneTree)[0] ?? null : null)
1106: 
1107:     // Dropping onto a singleView session (standalone, not in any group):
1108:     // save current group to background and start a new group from singleView
1109:     if (!targetKey && singleView) {
1110:       key = singleView
1111:       const newGroupId = Math.random().toString(36).slice(2)
1112:       const currentRank = syncedGroups[activeGroupId]?.rank ?? null
1113:       if (paneTree) {
1114:         void setGroupTree(activeGroupId, paneTree)
1115:         if (!currentRank) void setGroupRank(activeGroupId, generateKeyBetween(null, generateKeyBetween(currentRank, null)))
1116:       }
1117:       const newRank = generateKeyBetween(currentRank, null)
1118:       void setGroupTree(newGroupId, popOut(singleView))
1119:       void setGroupRank(newGroupId, newRank)
1120:       setPaneTree(popOut(singleView))
1121:       setActiveKey(singleView)
1122:       setActiveGroupId(newGroupId)
1123:       setSingleView(null)
1124:     }
1125: 
1126:     let splitTarget: { key: string; direction: 'h' | 'v'; newFirst?: boolean } | undefined
1127:     if (key) {
1128:       const direction: 'h' | 'v' = (edge === 'top' || edge === 'bottom') ? 'v' : 'h'
1129:       const newFirst = edge === 'left' || edge === 'top'
1130:       splitTarget = { key, direction, newFirst }
1131:       // Also set ref for dissolve-effect guard; handleCreateSession prefers direct param
1132:       splitTargetRef.current = splitTarget
1133:     }
1134:     const { host } = key ? parseSessionKey(key) : { host: undefined }
1135:     // Inherit the target pane's cwd so drop-to-split opens "here".
1136:     const sess = key ? sessionsRef.current.find(s => sessionKey(s) === key) : undefined
1137:     const panes = sess?.windows.flatMap(w => w.panes) ?? []
1138:     const cwd = panes.find(p => p.active)?.current_path || sess?.project_path || '~'
1139:     // Unique name so the optimistic pane-tree key can't collide with an
1140:     // existing leaf. A literal 'shell' would duplicate any live 'shell' leaf
1141:     // (shared pool entry) and get mangled when the server dedup migrates it.
1142:     const existingNames = new Set(sessionsRef.current.map(s => s.name))
1143:     let name = 'shell'
1144:     for (let n = 2; existingNames.has(name); n++) name = `shell-${n}`
