1418:               <div
1419:                 className="absolute bg-primary"
1420:                 style={{
1421:                   ...(mainDragOver.zone === 'left' && { left: 0, top: 0, bottom: 0, width: 1 }),
1422:                   ...(mainDragOver.zone === 'right' && { right: 0, top: 0, bottom: 0, width: 1 }),
1423:                   ...(mainDragOver.zone === 'top' && { top: 0, left: 0, right: 0, height: 1 }),
1424:                   ...(mainDragOver.zone === 'bottom' && { bottom: 0, left: 0, right: 0, height: 1 }),
1425:                 }}
1426:               />
1427:               {mainDragOver.zone === 'center' ? (
1428:                 <div className="absolute inset-0 bg-primary/10 border-2 border-dashed border-primary rounded-lg flex items-center justify-center">
1429:                   <span className="text-sm font-medium text-primary">+ Split</span>
1430:                 </div>
1431:               ) : (
1432:                 <div
1433:                   className="absolute bg-primary/10"
1434:                   style={{
1435:                     ...(mainDragOver.zone === 'left' && { left: 0, top: 0, bottom: 0, width: '50%' }),
1436:                     ...(mainDragOver.zone === 'right' && { right: 0, top: 0, bottom: 0, width: '50%' }),
1437:                     ...(mainDragOver.zone === 'top' && { top: 0, left: 0, right: 0, height: '50%' }),
1438:                     ...(mainDragOver.zone === 'bottom' && { bottom: 0, left: 0, right: 0, height: '50%' }),
1439:                   }}
1440:                 />
1441:               )}
1442:             </div>
1443:           )}
1444:           {(currentView as View) === 'setup' ? (
1445:             <Setup onComplete={() => navigateTo(null)} />
1446:           ) : currentView === 'session' && renderSingleView ? (
1447:             <div ref={terminalContainerRef} className="flex-1 flex flex-col overflow-hidden">
1448:               {(() => {
1449:                 // Resolve v2 session identity when bootstrap is ready
1450:                 let sessionId: string | undefined
1451:                 let ownerId: string | undefined
1452:                 let generation: string | undefined
1453:                 if (v2Enabled && v2State.state.catalogBootstrapped && renderSingleView) {
1454:                   const ref = keyToSessionRef(renderSingleView)
1455:                   const sess = selectSessionByRef(v2State.state.catalog, ref)
1456:                   if (sess) {
1457:                     sessionId = sess.id
1458:                     ownerId = sess.owner
1459:                     generation = sess._compat?.generation
1460:                   }
1461:                 }
1462:                 return (
1463:                   <Terminal
1464:                     sessionName={parseSessionKey(renderSingleView).name}
1465:                     hostId={parseSessionKey(renderSingleView).host || undefined}
1466:                     backend={sessions.find(s => sessionKey(s) === renderSingleView)?.backend}
1467:                     sessionId={sessionId}
1468:                     ownerId={ownerId}
1469:                     generation={generation}
1470:                     fullscreen={terminalFullscreen}
1471:                     onToggleFullscreen={toggleFullscreen}
1472:                     onOpenFile={(path) => wiki.openFile(
1473:                       path,
1474:                       renderSingleView ? cwdForKey(renderSingleView) : undefined,
1475:                       sessions.find(s => sessionKey(s) === renderSingleView)?.host,
1476:                       renderSingleView ? parseSessionKey(renderSingleView).name : undefined,
1477:                     )}
1478:                   />
1479:                 )
1480:               })()}
1481:             </div>
1482:           ) : currentView === 'session' && renderPaneTree ? (
1483:             <TiledView
1484:               tree={renderPaneTree}
1485:               activeKey={renderActiveKey}
1486:               onActivate={(key) => {
1487:                 if (v2Enabled && v2State.layoutId) {
1488:                   void v2State.workspaceCommand(v2State.layoutId, { action: 'select', ref: keyToSessionRef(key) })
1489:                     .catch(err => console.error('v2 select command failed:', err))
1490:                 } else {
1491:                   setActiveKey(key)
1492:                 }
1493:                 refocusTerminal()
1494:               }}
1495:               onClose={closePane}
1496:               onKill={killPane}
1497:               onPopOut={(key) => {
1498:                 if (v2Enabled && v2State.layoutId) {
1499:                   void v2State.workspaceCommand(v2State.layoutId, { action: 'pop_out', ref: keyToSessionRef(key) })
1500:                     .catch(err => console.error('v2 pop_out command failed:', err))
1501:                   return
1502:                 }
1503:                 popOutPane(key)
1504:               }}
1505:               onSplit={(key, direction) => {
1506:                 splitTargetRef.current = { key, direction }
1507:                 openNewSessionModal()
1508:               }}
1509:               onRatioChange={(path, ratio) => {
1510:                 if (v2Enabled && v2State.layoutId) {
1511:                   const record = v2State.state.workspace.record
1512:                   const splitId = record ? splitIdAtPath(record.tree, path) : undefined
1513:                   if (splitId) {
1514:                     void v2State.workspaceCommand(v2State.layoutId, { action: 'resize', split_id: splitId, ratio })
1515:                       .catch(err => console.error('v2 resize command failed:', err))
1516:                   }
1517:                   return
1518:                 }
1519:                 setPaneTree((prev: PaneTree | null) => {
1520:                   if (prev === null) return null
1521:                   return updateRatio(prev, path, ratio)
1522:                 })
1523:               }}
1524:               fullscreen={terminalFullscreen}
1525:               onToggleFullscreen={toggleFullscreen}
1526:               terminalContainerRef={terminalContainerRef}
1527:               onDropSession={handleDropSession}
1528:               onDropNewSession={handleDropNewSession}
1529:               onSwapPanes={(a, b) => {
1530:                 if (v2Enabled && v2State.layoutId) {
1531:                   void v2State.workspaceCommand(v2State.layoutId, { action: 'swap', a: keyToSessionRef(a), b: keyToSessionRef(b) })
1532:                     .catch(err => console.error('v2 swap command failed:', err))
1533:                   return
1534:                 }
1535:                 setPaneTree((prev: PaneTree | null) => prev ? swapLeaves(prev, a, b) : prev)
1536:               }}
1537:               onMovePanes={(sourceKey, targetKey, edge) => {
1538:                 if (v2Enabled && v2State.layoutId) {
1539:                   void v2State.workspaceCommand(v2State.layoutId, {
1540:                     action: 'move',
1541:                     source: keyToSessionRef(sourceKey),
1542:                     target: keyToSessionRef(targetKey),
1543:                     edge,
1544:                   }).catch(err => console.error('v2 move command failed:', err))
1545:                   return
1546:                 }
1547:                 setPaneTree((prev: PaneTree | null) => prev ? movePane(prev, sourceKey, targetKey, edge) : prev)
1548:               }}
1549:               getBackend={(key) => sessions.find(s => sessionKey(s) === key)?.backend}
1550:               getCwd={cwdForKey}
1551:               onOpenFile={wiki.openFile}
1552:             />
1553:           ) : (
1554:             <Overview
1555:               sessions={sessions}
1556:               onOpenFile={wiki.openFile}
1557:               hosts={hosts}
1558:               hiddenSet={sessionAttrs.hidden}
1559:               backgroundSet={sessionAttrs.background}
1560:               scheduleIDs={sessionAttrs.scheduleIDs}
1561:               onSessionSelect={handleSessionSelect}
1562:               getSessionEvents={getSessionEvents}
1563:               getSessionActivity={getSessionActivity}
1564:               isSessionInActiveTurn={isSessionInActiveTurn}
1565:               onJumpToSession={jumpToSession}
1566:               onDismissAlert={dismissEvent}
1567:               setSessionAttr={setSessionAttr}
1568:               onSessionKilled={removeSessionFromLayout}
1569:               layoutGroups={layoutGroups}
1570:             />
1571:           )}
1572:           {/* Single shared slot: the active pane portals its mobile key bar here,
1573:               so split views show one full-width bar instead of one per pane. */}
1574:           <div id="mobile-keybar-slot" className="flex-none" />
1575:           <SettingsDrawer
1576:             open={settingsOpen}
1577:             onClose={closeSettings}
1578:             pushState={pushState}
1579:             onPushSubscribe={pushSubscribe}
1580:             onPushUnsubscribe={pushUnsubscribe}
1581:             onLogout={onLogout}
1582:             version={serverVersion}
1583:             updateAvailable={updateAvailable}
1584:             binaryUpdate={selfUpdate.status}
1585:             onApplyUpdate={selfUpdate.apply}
1586:             updateApplying={selfUpdate.applying}
1587:             updateRestartMode={selfUpdate.restartMode}
1588:             updateError={selfUpdate.error}
1589:             updateChecking={selfUpdate.checking}
1590:             onCheckUpdate={selfUpdate.checkNow}
1591:           />
1592:         </div>
1593:         {wiki.target && (
1594:           <WikiPanel
1595:             filePath={wiki.target.path}
1596:             openNonce={wiki.target.nonce}
1597:             sessionCwd={wiki.target.cwd}
1598:             hostId={wiki.target.hostId}
1599:             session={wiki.target.session}
1600:             onClose={() => wiki.closePanel()}
1601:           />
1602:         )}
1603:       </div>
1604:     </div>
1605:   )
1606: }
1607: 
1608: export default function App() {
1609:   const prefsProvider = usePreferencesProvider()
1610:   const { loading, authRequired, needsSetup, authenticated, error: authError, setup, login, logout } = useAuth()
1611:   const [showOnboarding, setShowOnboarding] = useState(false)
1612: 
1613:   useEffect(() => {
1614:     const syncViewport = () => {
1615:       const viewport = window.visualViewport
1616:       const height = viewport?.height ?? window.innerHeight
1617:       const width = viewport?.width ?? window.innerWidth
1618:       document.documentElement.style.setProperty('--app-height', `${Math.round(height)}px`)
1619:       document.documentElement.style.setProperty('--app-width', `${Math.round(width)}px`)
1620:     }
1621: 
1622:     syncViewport()
1623:     window.addEventListener('resize', syncViewport)
1624:     window.visualViewport?.addEventListener('resize', syncViewport)
1625:     window.visualViewport?.addEventListener('scroll', syncViewport)
1626: 
1627:     return () => {
1628:       window.removeEventListener('resize', syncViewport)
1629:       window.visualViewport?.removeEventListener('resize', syncViewport)
1630:       window.visualViewport?.removeEventListener('scroll', syncViewport)
1631:     }
1632:   }, [])
1633: 
1634:   // Re-fetch preferences after login (initial fetch may have gotten 401)
1635:   useEffect(() => {
1636:     if (authenticated) {
1637:       prefsProvider.refetch()
1638:     }
1639:   }, [authenticated]) // eslint-disable-line react-hooks/exhaustive-deps
1640: 
1641:   // Apply last-used theme immediately (before auth) so login page is themed
1642:   useEffect(() => {
1643:     try {
1644:       const cached = localStorage.getItem('termyard:theme')
1645:       if (cached) {
1646:         applyTheme(cached)
1647:       }
1648:     } catch {}
1649:   }, [])
1650: 
1651:   // Apply theme when preferences load or theme changes, and cache for login page
1652:   useEffect(() => {
1653:     if (prefsProvider.loaded) {
1654:       applyTheme(prefsProvider.prefs.theme)
1655:       try {
1656:         localStorage.setItem('termyard:theme', prefsProvider.prefs.theme)
1657:       } catch {}
1658:     }
1659:   }, [prefsProvider.loaded, prefsProvider.prefs.theme])
1660: 
1661:   if (loading) {
1662:     return <div className="flex items-center justify-center h-full w-full bg-background" />
1663:   }
1664: 
1665:   if (authRequired && needsSetup) {
1666:     const handleSetup = async (password: string) => {
1667:       const ok = await setup(password)
1668:       if (ok) setShowOnboarding(true)
1669:       return ok
1670:     }
1671:     return <Login mode="setup" error={authError} onSubmit={handleSetup} />
1672:   }
1673: 
1674:   if (authRequired && !authenticated) {
1675:     return <Login mode="login" error={authError} onSubmit={login} />
1676:   }
1677: 
1678:   if (authenticated && showOnboarding) {
1679:     return (
1680:       <PreferencesContext.Provider value={prefsProvider}>
1681:         <Setup fullPage onComplete={() => {
1682:           setShowOnboarding(false)
1683:           try { localStorage.setItem('termyard:setup-seen', 'true') } catch {}
1684:         }} />
1685:       </PreferencesContext.Provider>
1686:     )
1687:   }
1688: 
1689:   return (
1690:     <PreferencesContext.Provider value={prefsProvider}>
1691:       <AppInner onLogout={authRequired ? logout : undefined} authenticated={authRequired ? authenticated : true} />
1692:     </PreferencesContext.Provider>
1693:   )
1694: }
